// femacs: port of src/macfont.m @ fd7afced403.
//
// **This file is the Cocoa (Core Text) font backend.**  `configure.ac` 2762 sets
// `ns_fontfile=macfont.o` for the Cocoa configuration while 2816 sets `nsfont.o` for the
// GNUstep one: the two are build alternatives, each defines a `font_driver` of its own, and
// both are rows of `docs/port-map.md`'s Swift table - a single Swift module cannot hold the
// pair (docs/ports/nsfont.md's header records the same finding from the other side).
//
// Unlike src/nsfont.m, this file *is* conditional: 23 `#if`s, all of them on
// `MAC_OS_X_VERSION_MIN_REQUIRED`/`MAX_ALLOWED`, `__LP64__` or `USE_CT_GLYPH_INFO`.  The port
// follows the file's own target (the Cocoa build on a current macOS, the same rule the lane
// adopted for nsfont's GNUstep target): the `MAC_OS_X_VERSION_MIN_REQUIRED < 10.x` arms and
// the `USE_CT_GLYPH_INFO` arms are not taken (`USE_CT_GLYPH_INFO` is defined nowhere in this
// tree - rc 3.164 records that the frozen macro table cannot decide this file, and
// `tools/check-cond-eval.py src/macfont.m` indeed reports 5 disagreements).  Each such arm is
// named in docs/ports/macfont.md.
//
// The round-1 unit is the **engine layer**: lines 111-1535 - the file's own types, macros and
// objects, and the 32 functions from `cfdata_to_lisp` (138) through `macfont_release_cache`
// (1517), plus the three helpers C forward-declares at 49-56 and defines at the end
// (`mac_font_get_advance_width_for_glyph` 3707, `mac_font_get_bounding_rect_for_glyph` 3714,
// `mac_font_create_available_families` 3721), which the boundary's `macfont_glyph_extents`
// and `macfont_copy_available_families_cache` call.  The rest is listed in
// docs/ports/macfont.md's `## Deferred` with a reason per function, and none of it is
// stubbed here.

import Foundation
import AppKit
import CoreText

// ==========================================================================
// Lane ABI: C types.
// ==========================================================================

/// C: `typedef struct Lisp_X *Lisp_Word; typedef Lisp_Word Lisp_Object;` (src/lisp.h
/// 311-323).  The pointee is incomplete in C too and a Swift pointer to a Swift type cannot
/// be a `@_cdecl` parameter, so the lane keeps the pointer alone (docs/ports/nsimage.md).
typealias Lisp_Object = UnsafeMutableRawPointer?

/// C: `typedef uint32_t UTF32Char;` (src/character.h 44) - a C typedef has no Swift spelling
/// of its own, so the port names it.
typealias UTF32Char = UInt32

/// C: `union vectorlike_header { ptrdiff_t size; }` (src/lisp.h 923-955) - one member.
struct vectorlike_header {
  var size: Int
}

/// C: `struct font_metrics` (src/font.h 414-417) - `short lbearing, rbearing, width, ascent,
/// descent;`.  Owner mirror: `femacs/src/font.rs` 196.  The same mirror is in
/// `femacs/platform/macos/nsfont.swift`; the two are one spelling once the ~9 files are one
/// module (PORTING.md 0.1-5, the lane's open item).
struct font_metrics {
  var lbearing: Int16
  var rbearing: Int16
  var width: Int16
  var ascent: Int16
  var descent: Int16
}

/// C: `struct font` (src/font.h 275-404), the **windowed** form this file's target has (the
/// members C guards with `#if defined (HAVE_WINDOW_SYSTEM)` at 323-397 are present).  Owner
/// mirror: `femacs/src/include/font.rs` (frozen configuration: `sizeof` 184, `driver`@176).
/// Measured here (`## Evidence`): `sizeof` 216, `props`@8, `min_width`@144, `pixel_size`@152,
/// `driver`@208.  No field is a Swift enum (the lane rule).
struct font {
  var header: vectorlike_header
  /// C: `Lisp_Object props[FONT_OBJECT_MAX];` (font.h 284) - 17 slots.
  var props: props17
  var min_width: Int32
  var max_width: Int32
  var pixel_size: Int32
  var height: Int32
  var space_width: Int32
  var average_width: Int32
  var ascent: Int32
  var descent: Int32
  var underline_thickness: Int32
  var underline_position: Int32
  var vertical_centering: Bool
  var baseline_offset: Int32
  var relative_compose: Int32
  var default_ascent: Int32
  var encoding_charset: Int32
  var repertory_charset: Int32
  /// C: `struct font_driver const *driver;` (font.h 400) - the driver record has an owner
  /// mirror (`femacs/src/font.rs` 266) but it is a C function-pointer table, so the pointer
  /// keeps the untyped form (P-55/P-72), as in nsfont.swift.
  var driver: UnsafeRawPointer?
}

/// C: `Lisp_Object props[FONT_OBJECT_MAX];` - a fixed-size array of 17 slots (a fixed-size
/// array is not a Swift value type).
struct props17 {
  var v0: Lisp_Object
  var v1: Lisp_Object
  var v2: Lisp_Object
  var v3: Lisp_Object
  var v4: Lisp_Object
  var v5: Lisp_Object
  var v6: Lisp_Object
  var v7: Lisp_Object
  var v8: Lisp_Object
  var v9: Lisp_Object
  var v10: Lisp_Object
  var v11: Lisp_Object
  var v12: Lisp_Object
  var v13: Lisp_Object
  var v14: Lisp_Object
  var v15: Lisp_Object
  var v16: Lisp_Object
}

