/// C: `struct macfont_metrics` (src/macfont.m 1162-1183).  Three of its members are C
/// bit-fields; the port stores the two allocation units the C compiler measured (`## Evidence`:
/// `sizeof` 8, `lbearing_low`@0, `rbearing_low`@1, the `lbearing_high`/`rbearing_high` unit@2,
/// `ascent_low`@3, `descent_low`@4, the `ascent_high`/`descent_high` unit@5, the
/// `width_frac`/`width_int` unit@6) and names the fields through the accessors below, the
/// P-80/1.3 convention for a bit-field run.
struct macfont_metrics {
  var lbearing_low: UInt8
  var rbearing_low: UInt8
  /// C: `signed lbearing_high : 4, rbearing_high : 4;`
  var lbearing_high_rbearing_high: UInt8
  var ascent_low: UInt8
  var descent_low: UInt8
  /// C: `signed ascent_high : 4, descent_high : 4;`
  var ascent_high_descent_high: UInt8
  /// C: `signed width_frac : WIDTH_FRAC_BITS, width_int : 16 - WIDTH_FRAC_BITS;` - one
  /// 16-bit unit, `width_frac` in its low 4 bits (clang, little-endian).
  var width_frac_width_int: Int16
}

