/// C: `struct OpenTypeSpec` (src/macfont.m 1866-1872) - `Lisp_Object script; unsigned int
/// script_tag, langsys_tag; int nfeatures[2]; unsigned int *features[2];`.  The two 2-element
/// arrays are tuples (a fixed-size array is not a Swift value type) with accessors, the shape
/// `macfont_info`'s run uses.
struct OpenTypeSpec {
  var script: Lisp_Object
  var script_tag: UInt32
  var langsys_tag: UInt32
  var nfeatures: (Int32, Int32)
  var features: (UnsafeMutablePointer<UInt32>?, UnsafeMutablePointer<UInt32>?)
}
fileprivate func otspec_nfeatures(_ s: UnsafeMutablePointer<OpenTypeSpec>, _ i: Int) -> Int32 {
  i == 0 ? s.pointee.nfeatures.0 : s.pointee.nfeatures.1
}
fileprivate func set_otspec_nfeatures(_ s: UnsafeMutablePointer<OpenTypeSpec>, _ i: Int,
                                      _ v: Int32) {
  if i == 0 { s.pointee.nfeatures.0 = v } else { s.pointee.nfeatures.1 = v }
}
fileprivate func otspec_features(_ s: UnsafeMutablePointer<OpenTypeSpec>, _ i: Int)
  -> UnsafeMutablePointer<UInt32>? {
  i == 0 ? s.pointee.features.0 : s.pointee.features.1
}
fileprivate func set_otspec_features(_ s: UnsafeMutablePointer<OpenTypeSpec>, _ i: Int,
                                     _ v: UnsafeMutablePointer<UInt32>?) {
  if i == 0 { s.pointee.features.0 = v } else { s.pointee.features.1 = v }
}

/// C: `#define OTF_SYM_TAG(SYM, TAG)` (src/macfont.m 1875-1880): the symbol name's first four
/// bytes, big-endian.  The C assigns to its second argument; the port returns the tag.
fileprivate func OTF_SYM_TAG(_ sym: Lisp_Object) -> UInt32 {
  let p = UnsafeMutableRawPointer(SDATA(SYMBOL_NAME(sym)))
    .assumingMemoryBound(to: UInt8.self)

  return UInt32(p[0]) << 24 | UInt32(p[1]) << 16 | UInt32(p[2]) << 8 | UInt32(p[3])
}

