/// C: `typedef UInt8 UINT24[3];` (src/macfont.m 3244) - a 3-byte big-endian field.
typealias UINT24 = (UInt8, UInt8, UInt8)

/// The UInt32/UInt16 members of the packed UVS records (src/macfont.m 3236-3281, inside
/// `#pragma pack(push, 1)`): stored as their bytes because Swift aligns a `UInt32`/`UInt16`
/// and C's packed layout does not.  Every read goes through the `BUINT*_VALUE` helpers, which
/// take the member's address, exactly as C's macros do.
typealias packed_uint32 = (UInt8, UInt8, UInt8, UInt8)
typealias packed_uint16 = (UInt8, UInt8)

