// C's `#define METRICS_VALUE(metrics, member)` and its three siblings (src/macfont.m
// 1184-1201) are macros over a *signed 4-bit* field; the port spells them as the four
// accessors below, which is the same arithmetic.

/// C: `((int) (((unsigned int) (metrics)->member##_high << 8) | (metrics)->member##_low))` -
/// `member_high` is signed, so it sign-extends before the shift.
fileprivate func METRICS_VALUE(_ high: UInt8, _ low: UInt8) -> Int32 {
  (sign_extend_4bit(high) << 8) | Int32(low)
}

/// C: `do {short tmp = (value); (metrics)->member##_low = tmp & 0xff; (metrics)->member##_high
/// = tmp >> 8;} while (0)` - the 4-bit field keeps the low nibble of `tmp >> 8`.
fileprivate func METRICS_SET_VALUE(_ value: Int32) -> (low: UInt8, high: UInt8) {
  let tmp = UInt16(truncatingIfNeeded: value)
  return (UInt8(tmp & 0xff), UInt8((tmp >> 8) & 0xf))
}

/// C's `signed x : 4` - clang sign-extends the 4-bit field.
fileprivate func sign_extend_4bit(_ nibble: UInt8) -> Int32 {
  let v = Int32(nibble & 0xf)
  return v >= 8 ? v - 16 : v
}

/// C: `signed width_frac : 4, width_int : 12;` (src/macfont.m 1181) - clang puts `width_frac`
/// in the unit's low 4 bits and sign-extends both.
fileprivate func width_frac(_ m: inout macfont_metrics) -> Int32 {
  sign_extend_4bit(UInt8(truncatingIfNeeded: m.width_frac_width_int & 0xf))
}
fileprivate func width_int(_ m: inout macfont_metrics) -> Int32 {
  let raw = Int32(m.width_frac_width_int) >> 4
  return raw
}
fileprivate func set_width_frac(_ m: inout macfont_metrics, _ v: Int32) {
  let unit = UInt16(bitPattern: m.width_frac_width_int)
  m.width_frac_width_int = Int16(bitPattern: (unit & ~0xf) | UInt16(v & 0xf))
}
fileprivate func set_width_int(_ m: inout macfont_metrics, _ v: Int32) {
  let unit = UInt16(bitPattern: m.width_frac_width_int)
  m.width_frac_width_int = Int16(bitPattern: (unit & 0xf) | (UInt16(truncatingIfNeeded: v) << 4))
}

/// C: `#define METRICS_STATUS(metrics) (METRICS_VALUE (metrics, ascent) + METRICS_VALUE
/// (metrics, descent))` (src/macfont.m 1197-1198).
fileprivate func METRICS_STATUS(_ m: inout macfont_metrics) -> Int32 {
  METRICS_VALUE(m.ascent_high_descent_high & 0x0f, m.ascent_low)
    + METRICS_VALUE((m.ascent_high_descent_high >> 4) & 0x0f, m.descent_low)
}
fileprivate func METRICS_SET_STATUS(_ m: inout macfont_metrics, _ status: Int32) {
  let a = METRICS_SET_VALUE(0)

  m.ascent_low = a.low
  m.ascent_high_descent_high = (m.ascent_high_descent_high & 0xf0) | a.high
  let d = METRICS_SET_VALUE(status)

  m.descent_low = d.low
  m.ascent_high_descent_high = (m.ascent_high_descent_high & 0x0f) | (d.high << 4)
}

// `struct macfont_info`'s five-bit run (src/macfont.m 89-93); the byte offsets and bit
// positions are the ones measured in `## Evidence`.

fileprivate func synthetic_italic_p(_ p: UnsafeMutablePointer<macfont_info>) -> Bool {
  p.pointee.bits_lo & (1 << 0) != 0
}
fileprivate func set_synthetic_italic_p(_ p: UnsafeMutablePointer<macfont_info>, _ v: Bool) {
  if v { p.pointee.bits_lo |= (1 << 0) } else { p.pointee.bits_lo &= ~(1 << 0) }
}
fileprivate func synthetic_bold_p(_ p: UnsafeMutablePointer<macfont_info>) -> Bool {
  p.pointee.bits_lo & (1 << 1) != 0
}
fileprivate func set_synthetic_bold_p(_ p: UnsafeMutablePointer<macfont_info>, _ v: Bool) {
  if v { p.pointee.bits_lo |= (1 << 1) } else { p.pointee.bits_lo &= ~(1 << 1) }
}
fileprivate func spacing(_ p: UnsafeMutablePointer<macfont_info>) -> UInt32 {
  UInt32((p.pointee.bits_lo >> 2) & 0x3)
}
fileprivate func set_spacing(_ p: UnsafeMutablePointer<macfont_info>, _ v: UInt32) {
  p.pointee.bits_lo = (p.pointee.bits_lo & ~(0x3 << 2)) | (UInt16(v & 0x3) << 2)
}
fileprivate func antialias(_ p: UnsafeMutablePointer<macfont_info>) -> UInt32 {
  UInt32((p.pointee.bits_lo >> 4) & 0x3)
}
fileprivate func set_antialias(_ p: UnsafeMutablePointer<macfont_info>, _ v: UInt32) {
  p.pointee.bits_lo = (p.pointee.bits_lo & ~(0x3 << 4)) | (UInt16(v & 0x3) << 4)
}
fileprivate func color_bitmap_p(_ p: UnsafeMutablePointer<macfont_info>) -> Bool {
  p.pointee.bits_lo & (1 << 6) != 0
}
fileprivate func set_color_bitmap_p(_ p: UnsafeMutablePointer<macfont_info>, _ v: Bool) {
  if v { p.pointee.bits_lo |= (1 << 6) } else { p.pointee.bits_lo &= ~(1 << 6) }
}

/// C: `#define BUINT8_VALUE(lval) (*((UInt8 *) &(lval)))` (src/macfont.m 3291); the macro takes
/// the member's address, which is what the port passes too.
fileprivate func BUINT8_VALUE(_ p: UnsafeRawPointer) -> UInt8 {
  p.assumingMemoryBound(to: UInt8.self)[0]
}
/// C: `#define BUINT16_VALUE(lval) OSReadBigInt16 (&(lval), 0)` (src/macfont.m 3294) - the same
/// two bytes, big-endian.
fileprivate func BUINT16_VALUE(_ p: UnsafeRawPointer) -> UInt16 {
  UInt16(p.assumingMemoryBound(to: UInt8.self)[0]) << 8
    | UInt16(p.assumingMemoryBound(to: UInt8.self)[1])
}
/// C: `#define BUINT24_VALUE(lval) (OSReadBigInt32 (&(lval), 0) >> 8)` (src/macfont.m 3295) -
/// the C reads four bytes from the three-byte field ("Succeeding one byte should also be
/// accessible"), and so does the port.
fileprivate func BUINT24_VALUE(_ p: UnsafeRawPointer) -> UInt32 {
  let b = p.assumingMemoryBound(to: UInt8.self)
  return (UInt32(b[0]) << 24 | UInt32(b[1]) << 16 | UInt32(b[2]) << 8 | UInt32(b[3])) >> 8
}
/// C: `#define BUINT32_VALUE(lval) OSReadBigInt32 (&(lval), 0)` (src/macfont.m 3296).
fileprivate func BUINT32_VALUE(_ p: UnsafeRawPointer) -> UInt32 {
  let b = p.assumingMemoryBound(to: UInt8.self)
  return UInt32(b[0]) << 24 | UInt32(b[1]) << 16 | UInt32(b[2]) << 8 | UInt32(b[3])
}

/// C's `(uintptr_t) ptr` / `(const void *) value` pair in `macfont_get_glyph_for_character`
/// (src/macfont.m 1581-1645): the cache's dictionary is created with NULL callbacks, so its
/// keys and values are the raw integers themselves.
fileprivate func uintptr(_ p: UnsafeRawPointer?) -> UInt {
  p == nil ? 0 : UInt(bitPattern: p!)
}

/// C: `cache->glyph.row_nkeys_or_perm[i]` (src/macfont.m 1564 and 1655-1682) - the record's
/// 256-byte array, which the port stores as a tuple and indexes through a rebound pointer.
fileprivate func row_nkeys_or_perm_at(_ p: UnsafeMutablePointer<macfont_cache>, _ i: Int) -> UInt8 {
  withUnsafeMutablePointer(to: &p.pointee.glyph.row_nkeys_or_perm) { bytes in
    bytes.withMemoryRebound(to: UInt8.self, capacity: 256) { $0[i] }
  }
}
fileprivate func set_row_nkeys_or_perm(_ p: UnsafeMutablePointer<macfont_cache>, _ i: Int,
                                       _ v: UInt8) {
  withUnsafeMutablePointer(to: &p.pointee.glyph.row_nkeys_or_perm) { bytes in
    bytes.withMemoryRebound(to: UInt8.self, capacity: 256) { $0[i] = v }
  }
}

