/// C: `cfdata_to_lisp` (src/macfont.m 138-146).
fileprivate func cfdata_to_lisp(_ data: CFData?) -> Lisp_Object {
  let len = CFDataGetLength(data!)
  let result = make_uninit_string(len)

  CFDataGetBytes(data!, CFRangeMake(0, len),
                 UnsafeMutableRawPointer(SDATA(result)).assumingMemoryBound(to: UInt8.self))

  return result
}

/// C: `cfstring_to_lisp_nodecode` (src/macfont.m 154-186).
fileprivate func cfstring_to_lisp_nodecode(_ string: CFString?) -> Lisp_Object {
  var result: Lisp_Object = Qnil()
  let s = CFStringGetCStringPtr(string!, CFStringBuiltInEncodings.UTF8.rawValue)

  if s != nil {
    var i: CFIndex = 0
    let length = CFStringGetLength(string!)

    while i < length {
      if CFStringGetCharacterAtIndex(string!, i) == 0 {
        break
      }
      i += 1
    }

    if i == length {
      return make_unibyte_string(s!, strlen(s!))
    }
  }

  let data = CFStringCreateExternalRepresentation(nil, string!, CFStringBuiltInEncodings.UTF8.rawValue, 0x3F)
  if data != nil {
    result = cfdata_to_lisp(data)
    // C's `CFRelease (data)` is ARC's here (a `Create`/`Copy` result is owned in Swift).
  }

  return result
}

/// C: `cfstring_create_with_string_noencode` (src/macfont.m 188-200).
fileprivate func cfstring_create_with_string_noencode(_ s: Lisp_Object) -> CFString? {
  var string = CFStringCreateWithBytes(nil,
                                       UnsafeMutableRawPointer(SDATA(s))
                                         .assumingMemoryBound(to: UInt8.self),
                                       SBYTES(s), CFStringBuiltInEncodings.UTF8.rawValue, false)

  if string == nil {
    /* Failed to interpret as UTF 8.  Fall back on Mac Roman.  */
    string = CFStringCreateWithBytes(nil,
                                     UnsafeMutableRawPointer(SDATA(s))
                                       .assumingMemoryBound(to: UInt8.self),
                                     SBYTES(s), CFStringBuiltInEncodings.macRoman.rawValue, false)
  }

  return string
}

/// C: `mac_font_get_weight` (src/macfont.m 202-208).
fileprivate func mac_font_get_weight(_ font: CTFont?) -> CFIndex {
  // C: `NSFont *nsFont = (NSFont *) font;` - `CTFont` and `NSFont` are toll-free bridged, so
  // the cast is the unwrap.
  let nsFont: NSFont = font!

  return CFIndex(NSFontManager.shared.weight(of: nsFont))
}

/// C: `mac_screen_font_get_advance_width_for_glyph` (src/macfont.m 210-217).
fileprivate func mac_screen_font_get_advance_width_for_glyph(_ font: UnsafeMutableRawPointer?,
                                                             _ glyph: CGGlyph) -> CGFloat {
  let advancement = Unmanaged<NSFont>.fromOpaque(font!).takeUnretainedValue()
    .advancement(forGlyph: NSGlyph(glyph))

  return advancement.width
}

/// C: `mac_font_get_glyph_for_cid` (src/macfont.m 219-265) - the `#if !USE_CT_GLYPH_INFO` arm
// (see the header comment: `USE_CT_GLYPH_INFO` is defined nowhere, so this is the live one; the
// `#else` arm is `mac_ctfont_get_glyph_for_cid`, 3995-4066, and macfont.h 70's
// `#define mac_font_get_glyph_for_cid mac_ctfont_get_glyph_for_cid` is not taken).
fileprivate func mac_font_get_glyph_for_cid(_ font: CTFont?,
                                            _ collection: NSCharacterCollection,
                                            _ cid: CGFontIndex) -> CGGlyph {
  var result: CGGlyph = kCGFontIndexInvalid
  let nsFont: NSFont = font!
  let characters: [unichar] = [0xfffd]
  let string = NSString(characters: characters, length: characters.count)
  let glyphInfo = NSGlyphInfo(characterIdentifier: Int(cid), collection: collection,
                              baseString: string as String)
  let attributes: [NSAttributedString.Key: Any] =
    [.font: nsFont, .glyphInfo: glyphInfo!]
  let textStorage = NSTextStorage(string: string as String, attributes: attributes)
  let layoutManager = NSLayoutManager()
  let textContainer = NSTextContainer()

  layoutManager.addTextContainer(textContainer)
  textStorage.addLayoutManager(layoutManager)

  /* Force layout.  */
  _ = layoutManager.glyphRange(for: textContainer)

  let fontInTextStorage = textStorage.attribute(.font, at: 0,
                                               effectiveRange: nil) as? NSFont

  if (fontInTextStorage as AnyObject?) === nsFont
      || fontInTextStorage?.fontName == nsFont.fontName {
    let glyph = layoutManager.glyph(at: 0)

    if glyph < NSGlyph(nsFont.numberOfGlyphs) {
      result = CGGlyph(truncatingIfNeeded: glyph)
    }
  }

  // C's `[textContainer release]`, `[layoutManager release]`, `[textStorage release]` are
  // ARC's here: the C's alloc/init +1 and each release are the reference's manual
  // memory management, which ARC performs (the ledger records the deviation).

  return result
}

/// C: `mac_screen_font_create_with_name` (src/macfont.m 268-276).
fileprivate func mac_screen_font_create_with_name(_ name: CFString?,
                                                  _ size: CGFloat) -> UnsafeMutableRawPointer? {
  let font = NSFont(name: name! as String, size: size)
  let result = font?.screen

  return result != nil ? Unmanaged.passRetained(result!).toOpaque() : nil
}

/// C: `mac_screen_font_get_metrics` (src/macfont.m 280-318).
fileprivate func mac_screen_font_get_metrics(_ font: UnsafeMutableRawPointer?,
                                             _ ascent: UnsafeMutablePointer<CGFloat>?,
                                             _ descent: UnsafeMutablePointer<CGFloat>?,
                                             _ leading: UnsafeMutablePointer<CGFloat>?) -> Bool {
  let nsFont = Unmanaged<NSFont>.fromOpaque(font!).takeUnretainedValue().printer

  let textStorage = NSTextStorage(string: " ")
  let layoutManager = NSLayoutManager()
  let textContainer = NSTextContainer()

  setFont(textStorage, nsFont)
  textContainer.lineFragmentPadding = 0

  layoutManager.addTextContainer(textContainer)
  textStorage.addLayoutManager(layoutManager)

  // C: `if (!(textStorage && layoutManager && textContainer)) { [textStorage release];
  // return false; }` (296-301) - the three objects are non-optional in Swift (the SDK's
  // initialisers do not return nil), so the check is recorded, not transcribed.

  let usedRect = layoutManager.lineFragmentUsedRect(forGlyphAt: 0, effectiveRange: nil)
  let spaceLocation = layoutManager.location(forGlyphAt: 0)

  ascent!.pointee = spaceLocation.y
  descent!.pointee = NSHeight(usedRect) - spaceLocation.y
  leading!.pointee = 0
  let descender = nsFont.descender
  if -descender < descent!.pointee {
    leading!.pointee = descent!.pointee + descender
    descent!.pointee = -descender
  }

  return true
}

/// C: `mac_font_shape_1` (src/macfont.m 329-591).  `RIGHT_TO_LEFT_P` (386) is `#define
/// RIGHT_TO_LEFT_P permutation` (the same alias nsfont.m has at 1304) - but here `permutation`
/// **is** allocated when the first glyph's bidi level is odd, so every branch behind the alias
/// is live text and the port keeps them (`permutation != nil`).
fileprivate func mac_font_shape_1(_ font: NSFont, _ string: NSString,
                                  _ glyph_layouts: UnsafeMutablePointer<mac_glyph_layout>,
                                  _ glyph_len: CFIndex,
                                  _ dir: lgstring_direction) -> CFIndex {
  var i: UInt
  var result: CFIndex = 0
  var textStorage: NSTextStorage
  var layoutManager: NSLayoutManager
  var textContainer: NSTextContainer
  var stringLength: UInt
  var spaceLocation = NSPoint()
  var used: UInt
  var numberOfGlyphs: UInt = 0

  _ = dir

  textStorage = NSTextStorage(string: string as String)
  layoutManager = NSLayoutManager()
  textContainer = NSTextContainer()

  /* Append a trailing space to measure baseline position.  */
  textStorage.append(NSAttributedString(string: " "))
  setFont(textStorage, font)
  textContainer.lineFragmentPadding = 0

  layoutManager.addTextContainer(textContainer)
  textStorage.addLayoutManager(layoutManager)

  // C: `if (!(textStorage && layoutManager && textContainer)) { [textStorage release];
  // return 0; }` (358-363) - recorded, not transcribed (see mac_screen_font_get_metrics).

  stringLength = UInt(string.length)

  /* Force layout.  */
  _ = layoutManager.glyphRange(for: textContainer)

  spaceLocation = layoutManager.location(forGlyphAt: Int(stringLength))

  /* Remove the appended trailing space because otherwise it may
     generate a wrong result for a right-to-left text.  */
  textStorage.beginEditing()
  textStorage.deleteCharacters(in: NSRange(location: Int(stringLength), length: 1))
  textStorage.endEditing()
  _ = layoutManager.glyphRange(for: textContainer)

  i = 0
  while i < stringLength {
    var range = NSRange()
    let fontInTextStorage =
      textStorage.attribute(.font, at: Int(i), longestEffectiveRange: &range,
                            in: NSRange(location: 0, length: Int(stringLength))) as? NSFont

    if !((fontInTextStorage as AnyObject?) === font
         || fontInTextStorage?.fontName == font.fontName) {
      break
    }
    i = UInt(NSMaxRange(range))
  }
  if i < stringLength {
    /* Make the test `used <= glyph_len' below fail if textStorage
       contained some fonts other than the specified one.  */
    used = UInt(glyph_len) + 1
  } else {
    var range = NSRange(location: 0, length: Int(stringLength))

    range = layoutManager.glyphRange(forCharacterRange: range, actualCharacterRange: nil)
    numberOfGlyphs = UInt(NSMaxRange(range))
    used = numberOfGlyphs
    i = 0
    while i < numberOfGlyphs {
      if layoutManager.notShownAttribute(forGlyphAt: Int(i)) {
        used -= 1
      }
      i += 1
    }
  }

  if 0 < used && used <= UInt(glyph_len) {
    var glyphIndex: UInt
    var prevGlyphIndex: UInt
    var bidiLevel: UInt8 = 0
    var permutation: UnsafeMutablePointer<UInt>?
    var compRange = NSRange()
    var range = NSRange()
    var totalAdvance: CGFloat

    glyphIndex = 0
    while layoutManager.notShownAttribute(forGlyphAt: Int(glyphIndex)) {
      glyphIndex += 1
    }

    /* For now we assume the direction is not changed within the
       string.  */
    _ = layoutManager.getGlyphs(in: NSRange(location: Int(glyphIndex), length: 1),
                                glyphs: nil, properties: nil, characterIndexes: nil,
                                bidiLevels: &bidiLevel)
    if bidiLevel & 1 != 0 {
      permutation = xmalloc(MemoryLayout<UInt>.size * Int(used))!
        .assumingMemoryBound(to: UInt.self)
    } else {
      permutation = nil
    }

    /* C: `#define RIGHT_TO_LEFT_P permutation` (386) - the alias' branches below are live.  */

    /* Fill the `comp_range' member of struct mac_glyph_layout, and
       setup a permutation for right-to-left text.  */
    compRange = NSRange(location: 0, length: 0)
    range = NSRange(location: 0, length: 0)
    while NSMaxRange(range) < Int(used) {
      let gl = glyph_layouts + NSMaxRange(range)
      var characterIndex = UInt(layoutManager.characterIndexForGlyph(at: Int(glyphIndex)))

      gl.pointee.string_index = CFIndex(characterIndex)

      if characterIndex >= UInt(NSMaxRange(compRange)) {
        compRange.location = NSMaxRange(compRange)
        repeat {
          var characterRange = string.rangeOfComposedCharacterSequence(at: Int(characterIndex))

          compRange.length = NSMaxRange(characterRange) - compRange.location
          _ = layoutManager.glyphRange(forCharacterRange: compRange,
                                       actualCharacterRange: &characterRange)
          characterIndex = UInt(NSMaxRange(characterRange) - 1)
        } while characterIndex >= UInt(NSMaxRange(compRange))

        if permutation != nil {
          var n = 0
          while n < range.length {
            permutation![range.location + n] = UInt(NSMaxRange(range) - n - 1)
            n += 1
          }
        }

        range = NSRange(location: NSMaxRange(range), length: 0)
      }

      gl.pointee.comp_range.location = compRange.location
      gl.pointee.comp_range.length = compRange.length

      glyphIndex += 1
      while glyphIndex < numberOfGlyphs {
        if !layoutManager.notShownAttribute(forGlyphAt: Int(glyphIndex)) {
          break
        }
        glyphIndex += 1
      }
      range.length += 1
    }
    if permutation != nil {
      var n = 0
      while n < range.length {
        permutation![range.location + n] = UInt(NSMaxRange(range) - n - 1)
        n += 1
      }
    }

    /* Then fill the remaining members.  */
    glyphIndex = 0
    prevGlyphIndex = 0
    while layoutManager.notShownAttribute(forGlyphAt: Int(glyphIndex)) {
      glyphIndex += 1
    }

    if permutation == nil {
      totalAdvance = 0
    } else {
      var nrects: UInt = 0
      let glyphRects =
        layoutManager.rectArray(forGlyphRange: NSRange(location: 0, length: Int(numberOfGlyphs)),
                                withinSelectedGlyphRange: NSRange(location: NSNotFound, length: 0),
                                in: textContainer, rectCount: &nrects)

      totalAdvance = NSMaxX(glyphRects![0])
    }

    i = 0
    while i < used {
      var gl: UnsafeMutablePointer<mac_glyph_layout>
      var location = NSPoint()
      var nextGlyphIndex: UInt
      var glyphRange = NSRange()
      var nrects: UInt = 0

      if permutation == nil {
        gl = glyph_layouts + Int(i)
      } else {
        let dest = permutation![Int(i)]

        gl = glyph_layouts + Int(dest)
        if i < dest {
          let tmp = gl.pointee.string_index

          gl.pointee.string_index = glyph_layouts[Int(i)].string_index
          glyph_layouts[Int(i)].string_index = tmp
        }
      }
      gl.pointee.glyph_id = CGGlyph(truncatingIfNeeded: layoutManager.glyph(at: Int(glyphIndex)))

      location = layoutManager.location(forGlyphAt: Int(glyphIndex))
      gl.pointee.baseline_delta = spaceLocation.y - location.y

      nextGlyphIndex = glyphIndex + 1
      while nextGlyphIndex < numberOfGlyphs {
        if !layoutManager.notShownAttribute(forGlyphAt: Int(nextGlyphIndex)) {
          break
        }
        nextGlyphIndex += 1
      }

      if permutation == nil {
        var maxX: CGFloat

        if prevGlyphIndex == 0 {
          glyphRange = NSRange(location: 0, length: Int(nextGlyphIndex))
        } else {
          glyphRange = NSRange(location: Int(glyphIndex), length: Int(nextGlyphIndex - glyphIndex))
        }
        let glyphRects =
          layoutManager.rectArray(forGlyphRange: glyphRange,
                                  withinSelectedGlyphRange: NSRange(location: NSNotFound, length: 0),
                                  in: textContainer, rectCount: &nrects)
        maxX = max(NSMaxX(glyphRects![0]), totalAdvance)
        gl.pointee.advance_delta = location.x - totalAdvance
        gl.pointee.advance = maxX - totalAdvance
        totalAdvance = maxX
      } else {
        var minX: CGFloat

        if nextGlyphIndex == numberOfGlyphs {
          glyphRange = NSRange(location: Int(prevGlyphIndex),
                               length: Int(numberOfGlyphs - prevGlyphIndex))
        } else {
          glyphRange = NSRange(location: Int(prevGlyphIndex),
                               length: Int(glyphIndex + 1 - prevGlyphIndex))
        }
        let glyphRects =
          layoutManager.rectArray(forGlyphRange: glyphRange,
                                  withinSelectedGlyphRange: NSRange(location: NSNotFound, length: 0),
                                  in: textContainer, rectCount: &nrects)
        minX = min(NSMinX(glyphRects![0]), totalAdvance)
        gl.pointee.advance = totalAdvance - minX
        totalAdvance = minX
