@_silgen_name("colorWithUnsignedLong")
func colorWithUnsignedLong(_ cls: UnsafeMutableRawPointer?, _ c: UInt) -> NSColor?

/// C's `[textStorage setFont: font]` (src/macfont.m 295 and 349) is an Objective-C method
/// that **macOS does not implement** (AppKit declares no `-[NSTextStorage setFont:]`; the
/// reference compiles only because an Objective-C message send is not checked against the
/// interface, and at runtime the selector is not recognised there).  The port therefore
/// performs the same effect with a **public API** - the font attribute over the storage's
/// whole range - instead of reaching for a symbol no provider defines (`## Decisions`,
/// deviation 1).  Set `textStorage`'s font.
fileprivate func setFont(_ textStorage: NSTextStorage?, _ font: NSFont?) {
