fileprivate func get_cgcolor(_ color: UInt) -> CGColor? {
  let nsColor = colorWithUnsignedLong(unsafeBitCast(NSColor.self,
                                                    to: UnsafeMutableRawPointer.self), color)!

  nsColor.set()
  let colorSpace = nsColor.colorSpace.cgColorSpace
  let noc = nsColor.numberOfComponents
  let components = xmalloc(MemoryLayout<CGFloat>.size * (1 + noc))!
    .assumingMemoryBound(to: CGFloat.self)

  nsColor.getComponents(components)
  let cgColor = CGColor(colorSpace: colorSpace!, components: components)
  xfree(UnsafeMutableRawPointer(components))
  return cgColor
}

