/// C: `macfont_store_utf32char_to_unichars` (src/macfont.m 769-786).
fileprivate func macfont_store_utf32char_to_unichars(_ c_in: UTF32Char,
                                                     _ unichars: UnsafeMutablePointer<unichar>) -> CFIndex {
  var c = c_in

  if c < 0x10000 {
    unichars[0] = unichar(truncatingIfNeeded: c)

    return 1
  } else {
    c -= 0x10000
    unichars[0] = unichar(truncatingIfNeeded: (c >> 10) + 0xD800)
    unichars[1] = unichar(truncatingIfNeeded: (c & 0x3FF) + 0xDC00)

    return 2
  }
}

