  /* Getting symbolic traits with kCFNumberSInt32Type is lossy on Mac
     OS X 10.6 when the value is greater than or equal to 1 << 31.  */
  if CFNumberGetValue(number, CFNumberType.sInt64Type, &sint64_value) {
    sym_traits!.pointee = CTFontSymbolicTraits(rawValue: UInt32(truncatingIfNeeded: sint64_value))

