/// C: `mac_font_descriptor_get_adjusted_weight` (src/macfont.m 806-835).  C's
/// `CFRelease (font)`/`CFRelease (name)` are ARC's here (a `Create`/`Copy` result is owned in
/// Swift), so they are dropped - the ledger records the deviation.
fileprivate func mac_font_descriptor_get_adjusted_weight(_ desc: CTFontDescriptor?,
                                                        _ val_in: CGFloat) -> CGFloat {
  var val = val_in
  let percent_val = lround(val * 100)

  if percent_val == -40 {
    var font: CTFont? = nil
    let name = CTFontDescriptorCopyAttribute(desc!, kCTFontNameAttribute)

    if name != nil {
      let nameStr: CFString = name as! CFString

      font = CTFontCreateWithName(nameStr, 0, nil)
    }
    if font != nil {
      let weight = mac_font_get_weight(font)

      /* Workaround for crash when displaying Oriya characters
         with Arial Unicode MS on OS X 10.11.  */
      if weight == 5 {
        val = 0
      }
    }
  }

  return val
}

