fileprivate func macfont_invalidate_family_cache() {
  if HASH_TABLE_P(macfont_family_cache) {
    let h = XHASH_TABLE(macfont_family_cache)
    let size = HASH_TABLE_SIZE(h)
    var i = 0

    while i < size {
      if !hash_unused_entry_key_p(HASH_KEY(h, i)) {
        let value = HASH_VALUE(h, i)

        if mint_ptrp(value) {
          Unmanaged<CFString>.fromOpaque(xmint_pointer(value)!).release()
        }
      }
      i += 1
    }
    macfont_family_cache = Qnil()
  }
