fileprivate func macfont_get_family_cache_if_present(_ symbol: Lisp_Object,
                                                     _ string: UnsafeMutablePointer<CFString?>?) -> Bool {
  if HASH_TABLE_P(macfont_family_cache) {
    let h = XHASH_TABLE(macfont_family_cache)
    let i = hash_find(h, symbol)

    if i >= 0 {
      let value = HASH_VALUE(h, i)

      string!.pointee = mint_ptrp(value)
        ? Unmanaged<CFString>.fromOpaque(xmint_pointer(value)!).takeUnretainedValue() : nil

      return true
