fileprivate func macfont_set_family_cache(_ symbol: Lisp_Object, _ string: CFString?) {
  if !HASH_TABLE_P(macfont_family_cache) {
    withUnsafeTemporaryAllocation(of: Lisp_Object.self, capacity: 2) { args in
      args[0] = QCtest()
      args[1] = Qeq()
      macfont_family_cache = Fmake_hash_table(2, args.baseAddress)
    }
  }

  let h = XHASH_TABLE(macfont_family_cache)
  var hash: UInt32 = 0
  let i = hash_find_get_hash(h, symbol, &hash)
  let value = string != nil
    ? make_mint_ptr(Unmanaged<CFString>.passRetained(string!).toOpaque()) : Qnil()

  if i >= 0 {
    let old_value = HASH_VALUE(h, i)

    if mint_ptrp(old_value) {
      Unmanaged<CFString>.fromOpaque(xmint_pointer(old_value)!).release()
    }
    set_hash_value_slot(h, i, value)
  } else {
    _ = hash_put(h, symbol, value, hash)
  }
