  var attributes: CFDictionary?
  if family_name != nil {
    withUnsafePointer(to: kCTFontFamilyNameAttribute) { keyPtr in
      withUnsafePointer(to: family_name!) { valuePtr in
        withUnsafePointer(to: kCFTypeDictionaryKeyCallBacks) { keyCallbacks in
          withUnsafePointer(to: kCFTypeDictionaryValueCallBacks) { valueCallbacks in
            attributes = CFDictionaryCreate(nil,
                                            UnsafeMutablePointer(mutating:
                                              UnsafeRawPointer(keyPtr)
                                                .assumingMemoryBound(to: UnsafeRawPointer?.self)),
                                            UnsafeMutablePointer(mutating:
                                              UnsafeRawPointer(valuePtr)
                                                .assumingMemoryBound(to: UnsafeRawPointer?.self)),
                                            1, keyCallbacks, valueCallbacks)
