fileprivate func macfont_monospace_width_multiplier(_ font: UnsafeMutablePointer<font>?,
                                                    _ width: CGFloat) -> Int32 {
  let macfont_info = UnsafeMutableRawPointer(font!).assumingMemoryBound(to: macfont_info.self)
  var multiplier: Int32 = 0

  if spacing(macfont_info) == MACFONT_SPACING_MONO
      && font!.pointee.space_width != 0 {
    multiplier = Int32(lround(width / CGFloat(font!.pointee.space_width)))
    if multiplier == 1
        || lround(width / CGFloat(multiplier)) != Int(font!.pointee.space_width) {
      multiplier = 0
    }
  }

  return multiplier
}

