               MemoryLayout<UnsafeMutablePointer<macfont_metrics>?>.size * Int(row + 1))!
        .assumingMemoryBound(to: UnsafeMutablePointer<macfont_metrics>?.self)
    memset(UnsafeMutableRawPointer(macfont_info.pointee.metrics!
                                    + Int(macfont_info.pointee.metrics_nrows)),
           0,
           MemoryLayout<UnsafeMutablePointer<macfont_metrics>?>.size
             * Int(row + 1 - Int32(macfont_info.pointee.metrics_nrows)))
    macfont_info.pointee.metrics_nrows = Int16(row + 1)
