  if macfont_info.pointee.metrics![Int(row)] == nil {
    let new = xmalloc(MemoryLayout<macfont_metrics>.size * Int(METRICS_NCOLS_PER_ROW))!
      .assumingMemoryBound(to: macfont_metrics.self)
