/// C: `macfont_lookup_cache` (src/macfont.m 1463-1507).
fileprivate func macfont_lookup_cache(_ key: CFString) -> UnsafeMutablePointer<macfont_cache>? {
  var cache: UnsafeMutablePointer<macfont_cache>?

  if macfont_cache_dictionary == nil {
    withUnsafePointer(to: kCFTypeDictionaryKeyCallBacks) { keys in
      macfont_cache_dictionary = CFDictionaryCreateMutable(nil, 0, keys, nil)
    }
    cache = nil
  } else {
    let value = CFDictionaryGetValue(macfont_cache_dictionary!,
                                     UnsafeRawPointer(Unmanaged
                                       .passUnretained(key).toOpaque()))

    cache = value != nil
      ? UnsafeMutableRawPointer(mutating: value!).assumingMemoryBound(to: macfont_cache.self)
      : nil
  }

  if cache == nil {
    let macfont: CTFont? = CTFontCreateWithName(key, 0, nil)

    if macfont != nil {
      cache = xzalloc(MemoryLayout<macfont_cache>.size)!
        .assumingMemoryBound(to: macfont_cache.self)
      /* Treat the LastResort font as if it contained glyphs for
         all characters.  This may look too rough, but neither
         CTFontCopyCharacterSet nor -[NSFont coveredCharacterSet]
         for this font is correct for non-BMP characters on Mac OS
         X 10.5, anyway.  */
      if CFEqual(key, "LastResort" as CFString) {
        let range = CFRangeMake(0, CFIndex(MAX_UNICODE_CHAR()) + 1)

        cache!.pointee.cf_charset = CFCharacterSetCreateWithCharactersInRange(nil, range)
      }
      if cache!.pointee.cf_charset == nil {
        cache!.pointee.cf_charset = CTFontCopyCharacterSet(macfont!)
      }
      CFDictionaryAddValue(macfont_cache_dictionary!,
                           UnsafeRawPointer(Unmanaged.passUnretained(key).toOpaque()),
                           UnsafeRawPointer(cache!))
    }
  }

  return cache
}

/// C: `macfont_retain_cache` (src/macfont.m 1509-1515).
fileprivate func macfont_retain_cache(_ cache: UnsafeMutablePointer<macfont_cache>?)
  -> UnsafeMutablePointer<macfont_cache>? {
  cache!.pointee.reference_count += 1

  return cache
}

/// C: `macfont_release_cache` (src/macfont.m 1517-1534).  C's two
/// `memset (&cache->…, 0, sizeof (cache->…))` are the zero values of the two nested records,
/// and its `CFRelease`s of manually-retained fields are the ports' `nil` assignments (ARC) -
/// the record itself is not freed by C either, so the port matches that.
fileprivate func macfont_release_cache(_ cache: UnsafeMutablePointer<macfont_cache>?) {
  cache!.pointee.reference_count -= 1
