    xfree(UnsafeMutableRawPointer(cache!.pointee.glyph.matrix))
    if cache!.pointee.glyph.dictionary != nil {
      cache!.pointee.glyph.dictionary = nil
    }
    // C: `memset (&cache->glyph, 0, sizeof (cache->glyph));`
    withUnsafeMutablePointer(to: &cache!.pointee.glyph) { p in
      UnsafeMutableRawPointer(p).assumingMemoryBound(to: UInt8.self)
        .update(repeating: 0, count: MemoryLayout<macfont_cache_glyph>.size)
    }
    if cache!.pointee.uvs.table != nil {
      cache!.pointee.uvs.table = nil
    }
    // C: `memset (&cache->uvs, 0, sizeof (cache->uvs));`
    withUnsafeMutablePointer(to: &cache!.pointee.uvs) { p in
      UnsafeMutableRawPointer(p).assumingMemoryBound(to: UInt8.self)
        .update(repeating: 0, count: MemoryLayout<macfont_cache_uvs>.size)
