fileprivate func mac_font_get_glyphs_for_variants(_ uvs_table: CFData?,
                                                  _ c: UTF32Char,
                                                  _ selectors: UnsafePointer<UTF32Char>,
                                                  _ glyphs: UnsafeMutablePointer<CGGlyph>,
                                                  _ count: CFIndex) {
  let uvs = UnsafeRawPointer(CFDataGetBytePtr(uvs_table)!)
  let records = uvs + SIZEOF_UVS_TABLE_HEADER
  var i: CFIndex = 0
  var ir: UInt32 = 0
  let nrecords = BUINT32_VALUE(uvs + 6)

  while i < count && ir < nrecords {
    let record = records + Int(ir) * MemoryLayout<variation_selector_record>.size
    let var_selector = BUINT24_VALUE(record + RECORD_VAR_SELECTOR)

    if selectors[Int(i)] < var_selector {
      glyphs[Int(i)] = kCGFontIndexInvalid
      i += 1
      continue
    } else if selectors[Int(i)] > var_selector {
      ir += 1
      continue
    }

    /* selectors[i] == BUINT24_VALUE (records[ir].var_selector) */
    // C: `BUINT32_VALUE (records[ir].default_uvs_offset)` and its `non_default_` sibling.
    let default_uvs_offset = BUINT32_VALUE(record + RECORD_DEFAULT_UVS_OFFSET)
    let non_default_uvs_offset = BUINT32_VALUE(record + RECORD_NON_DEFAULT_UVS_OFFSET)

    glyphs[Int(i)] = kCGFontIndexInvalid

    if default_uvs_offset != 0 {
      let default_uvs = uvs + Int(default_uvs_offset)
      let ranges = default_uvs + Int(SIZEOF_DEFAULT_UVS_TABLE_HEADER)
      var lo: UInt32
      var hi: UInt32

      lo = 0
      hi = BUINT32_VALUE(default_uvs)
      while lo < hi {
        let mid = (lo + hi) / 2
        let range = ranges + Int(mid) * MemoryLayout<unicode_value_range>.size

        if c < BUINT24_VALUE(range) {
          hi = mid
        } else {
          lo = mid + 1
        }
      }
      if hi > 0 {
        let range = ranges + Int(hi - 1) * MemoryLayout<unicode_value_range>.size

        if c <= (BUINT24_VALUE(range) + UInt32(range.assumingMemoryBound(to: UInt8.self)[3])) {
          glyphs[Int(i)] = 0
        }
      }
    }

    if glyphs[Int(i)] == kCGFontIndexInvalid && non_default_uvs_offset != 0 {
      let non_default_uvs = uvs + Int(non_default_uvs_offset)
      let mappings = non_default_uvs + Int(SIZEOF_NON_DEFAULT_UVS_TABLE_HEADER)
      var lo: UInt32
      var hi: UInt32

      lo = 0
      hi = BUINT32_VALUE(non_default_uvs)
      while lo < hi {
        let mid = (lo + hi) / 2
        let mapping = mappings + Int(mid) * MemoryLayout<uvs_mapping>.size

        if c < BUINT24_VALUE(mapping) {
          hi = mid
        } else {
          lo = mid + 1
        }
      }
      if hi > 0 {
        let mapping = mappings + Int(hi - 1) * MemoryLayout<uvs_mapping>.size

        if BUINT24_VALUE(mapping) == c {
          glyphs[Int(i)] = BUINT16_VALUE(mapping + 3)
        }
      }
    }
    i += 1
    ir += 1
  }
  while i < count {
    glyphs[Int(i)] = kCGFontIndexInvalid
    i += 1
  }
}

/// C: `macfont_variation_glyphs` (src/macfont.m 3520-3573).
fileprivate func macfont_variation_glyphs(_ font: UnsafeMutablePointer<font>?, _ c: Int32,
                                          _ variations: UnsafeMutablePointer<UInt32>?) -> Int32 {
  var uvs_table: CFData?
  var uvs_collection = NSCharacterCollection.identityMappingCharacterCollection
  var i: Int32
  var n: Int32 = 0

  block_input()
  uvs_table = macfont_get_uvs_table(font, &uvs_collection)

  if uvs_table != nil {
    var selectors = [UTF32Char](repeating: 0, count: 256)
    var glyphs = [CGGlyph](repeating: 0, count: 256)

    i = 0
    while i < 16 {
      selectors[Int(i)] = 0xFE00 + UTF32Char(i)
      i += 1
    }
    while i < 256 {
      selectors[Int(i)] = 0xE0100 + UTF32Char(i - 16)
      i += 1
    }
    mac_font_get_glyphs_for_variants(uvs_table, UTF32Char(c), &selectors, &glyphs, 256)
    i = 0
    while i < 256 {
      var glyph = glyphs[Int(i)]

      if uvs_collection != NSCharacterCollection.identityMappingCharacterCollection
          && glyph != kCGFontIndexInvalid {
        glyph = macfont_get_glyph_for_cid(font, uvs_collection, glyph)
      }
      if glyph == kCGFontIndexInvalid {
        variations![Int(i)] = 0
      } else {
        variations![Int(i)] = (glyph != 0 ? UInt32(glyph)
                               : UInt32(truncatingIfNeeded:
                                          macfont_get_glyph_for_character(font, UTF32Char(c))))
        n += 1
      }
      i += 1
    }
  }
  unblock_input()

  return n
}

/// C: `static const char *const macfont_booleans[] = { ":antialias", ":minspace", NULL };` and
/// `macfont_non_booleans[]` (src/macfont.m 3576-3586) - the two NULL-terminated name tables
/// `macfont_filter_properties` hands to `font_filter_properties`.  Their only reader is that
/// one call, so the port spells the C strings at the point of use (`withCString`), which gives
/// them C's static lifetime for the duration of the call.
fileprivate func macfont_filter_properties(_ font: Lisp_Object, _ alist: Lisp_Object) {
  ":antialias".withCString { (a: UnsafePointer<CChar>) in
    ":minspace".withCString { (m: UnsafePointer<CChar>) in
      ":lang".withCString { (l: UnsafePointer<CChar>) in
        ":script".withCString { (s: UnsafePointer<CChar>) in
          ":destination".withCString { (d: UnsafePointer<CChar>) in
            var booleans: [UnsafePointer<CChar>?] = [a, m, nil]
            var non_booleans: [UnsafePointer<CChar>?] = [l, s, d, nil]

            booleans.withUnsafeMutableBufferPointer { b in
              non_booleans.withUnsafeMutableBufferPointer { nb in
                font_filter_properties(font, alist, b.baseAddress, nb.baseAddress)
              }
            }
          }
        }
      }
    }
  }
}



/// C: `mac_font_descriptor_supports_languages` (src/macfont.m 3581-3615).  C's `CFRelease
/// (desc_languages)` is ARC's (a `Copy` result).
fileprivate func mac_font_descriptor_supports_languages(_ descriptor: CTFontDescriptor?,
                                                        _ languages: CFArray?) -> Bool {
  var result = true
  let desc_languages = CTFontDescriptorCopyAttribute(descriptor!, kCTFontLanguagesAttribute)

  if desc_languages == nil {
    result = false
  } else {
    let descLanguages = desc_languages as! CFArray
    let range = CFRangeMake(0, CFArrayGetCount(descLanguages))
    let languages_count = CFArrayGetCount(languages)
    var i: CFIndex = 0

    while i < languages_count {
      let language = Unmanaged<CFString>.fromOpaque(
        CFArrayGetValueAtIndex(languages, i)!).takeUnretainedValue()

      if !CFArrayContainsValue(descLanguages, range,
                               UnsafeRawPointer(Unmanaged.passUnretained(language).toOpaque()))
          /* PingFang SC contains "zh" and "zh-Hant" as covered
             languages, but does not contain "zh-Hans".  */
          && !(CFEqual(language, "zh-Hans" as CFString)
               && CFArrayContainsValue(descLanguages, range,
                                       UnsafeRawPointer(Unmanaged.passUnretained("zh" as CFString)
                                         .toOpaque()))) {
        result = false
        break
      }
      i += 1
    }
  }

  return result
}

/// C: `mac_font_create_preferred_family_for_attributes` (src/macfont.m 3617-3705).  The
/// `MAC_OS_X_VERSION_MIN_REQUIRED < 1090` arms (3655-3665) are dead for this target, so the
/// `keys` table is C's `kCTLanguageAttributeName` arm, the `CTGetCoreTextVersion ()` branch is
/// not there, and the `result != NULL` early exit that branch's dead code needs is not either.
/// C's `CFRelease`s of `attrs`/`attr_string`/`ctline` are ARC's here.
fileprivate func mac_font_create_preferred_family_for_attributes(_ attributes: CFDictionary?)
  -> CFString? {
  var result: CFString? = nil
  let charset_string = CFDictionaryGetValue(attributes!,
                                            UnsafeRawPointer(Unmanaged.passUnretained(
                                              MAC_FONT_CHARACTER_SET_STRING_ATTRIBUTE).toOpaque()))

  if charset_string != nil
      && CFStringGetLength(Unmanaged<CFString>.fromOpaque(charset_string!)
        .takeUnretainedValue()) > 0 {
    var keys: [UnsafeRawPointer?] = [
      UnsafeRawPointer(Unmanaged.passUnretained(kCTLanguageAttributeName).toOpaque())
    ]
    var values: [UnsafeRawPointer?] = [nil]
    var num_values: CFIndex = 0
    let languages_ptr = CFDictionaryGetValue(attributes!,
                                             UnsafeRawPointer(Unmanaged.passUnretained(
                                               kCTFontLanguagesAttribute).toOpaque()))

    if languages_ptr != nil {
      let languages = Unmanaged<CFArray>.fromOpaque(languages_ptr!).takeUnretainedValue()

      if CFArrayGetCount(languages) > 0 {
        values[Int(num_values)] = CFArrayGetValueAtIndex(languages, 0)
        num_values += 1
      }
    }
    if result == nil {
      var attr_string: CFAttributedString? = nil
      var ctline: CTLine? = nil
      let attrs: CFDictionary? = keys.withUnsafeMutableBufferPointer { kb in
        values.withUnsafeMutableBufferPointer { vb in
          withUnsafePointer(to: kCFTypeDictionaryKeyCallBacks) { keyCallbacks in
            withUnsafePointer(to: kCFTypeDictionaryValueCallBacks) { valueCallbacks in
              CFDictionaryCreate(nil, kb.baseAddress, vb.baseAddress, num_values,
                                 keyCallbacks, valueCallbacks)
            }
          }
        }
      }

      if attrs != nil {
        attr_string = CFAttributedStringCreate(nil,
                                               Unmanaged<CFString>.fromOpaque(charset_string!)
                                                 .takeUnretainedValue(), attrs!)
      }
      if attr_string != nil {
        ctline = CTLineCreateWithAttributedString(attr_string!)
      }
      if ctline != nil {
        let runs = CTLineGetGlyphRuns(ctline!)
        let nruns = CFArrayGetCount(runs)
        var font: CTFont? = nil
        var i: CFIndex = 0

        while i < nruns {
          let run = Unmanaged<CTRun>.fromOpaque(CFArrayGetValueAtIndex(runs, i)!)
            .takeUnretainedValue()
          /* C's `CFDictionaryRef attributes = CTRunGetAttributes (run); if (attributes == NULL)
             break;` shadows the parameter; Swift imports the copy as non-optional (NULL comes
             only from a NULL run, which the array walk cannot produce), so the guard has no
             spelling here.  */
          let attributes: CFDictionary = CTRunGetAttributes(run)
          let font_in_run = CFDictionaryGetValue(attributes,
                                                 UnsafeRawPointer(Unmanaged.passUnretained(
                                                   kCTFontAttributeName).toOpaque()))

          if font_in_run == nil {
            break
          }
          let fontInRun = Unmanaged<CTFont>.fromOpaque(font_in_run!).takeUnretainedValue()

          if i == 0 {
            font = fontInRun
          } else if !mac_font_equal_in_postscript_name(font, fontInRun) {
            break
          }
          i += 1
        }
        if nruns > 0 && i == nruns {
          let family = CTFontCopyAttribute(font!, kCTFontFamilyNameAttribute)

          result = family == nil ? nil : (family as! CFString)
        }
      }
    }
  }

  return result
}
/// C: `macfont_get_cache` (src/macfont.m 1793-1799).  C's `Display_Info` is this lane's
/// `struct ns_display_info` alias (src/nsterm.h): the port reads
/// `FRAME_DISPLAY_INFO (f)->name_list_element`, so the frame-side accessor is the entry and this
/// function's result is that field.
fileprivate func macfont_get_cache(_ f: UnsafeMutableRawPointer?) -> Lisp_Object {
  let dpyinfo = FRAME_DISPLAY_INFO(f)

  return dpyinfo!.pointee.name_list_element
}

/// C: `macfont_traits_distance` (src/macfont.m 2230-2248).
fileprivate func macfont_traits_distance(_ sym_traits1: CTFontSymbolicTraits,
                                         _ sym_traits2: CTFontSymbolicTraits) -> Int32 {
  let diff = sym_traits1.symmetricDifference(sym_traits2)
  var distance: Int32 = 0

  /* We prefer synthetic bold of italic to synthetic italic of bold
     when both bold and italic are available but bold-italic is not
     available.  */
  if diff.contains(CTFontSymbolicTraits.traitBold) {
    distance |= (1 << 0)
  }
  if diff.contains(CTFontSymbolicTraits.traitItalic) {
    distance |= (1 << 1)
  }
  if diff.contains(CTFontSymbolicTraits.traitMonoSpace) {
    distance |= (1 << 2)
  }

  return distance
}

/// C: `macfont_closest_traits_index_p` (src/macfont.m 2250-2273).  C stores the traits in the
/// array as `uintptr_t`-cast pointers, which the port reads with `UInt(bitPattern:)`.
fileprivate func macfont_closest_traits_index_p(_ traits_array: CFArray?,
                                                _ target: CTFontSymbolicTraits,
                                                _ index: CFIndex) -> Bool {
  let count = CFArrayGetCount(traits_array)
  var traits: CTFontSymbolicTraits
  var my_distance: Int32
  var i: CFIndex

  traits = CTFontSymbolicTraits(rawValue: UInt32(truncatingIfNeeded:
    UInt(bitPattern: CFArrayGetValueAtIndex(traits_array, index))))
  my_distance = macfont_traits_distance(target, traits)

  i = 0
  while i < count {
    if i != index {
      traits = CTFontSymbolicTraits(rawValue: UInt32(truncatingIfNeeded:
        UInt(bitPattern: CFArrayGetValueAtIndex(traits_array, i))))
      if macfont_traits_distance(target, traits) < my_distance {
        return false
      }
    }
    i += 1
  }

  return true
}

/// C: `macfont_free_entity` (src/macfont.m 2650-2660).  The `CFRelease` is the manual +1
/// `macfont_descriptor_entity` handed into the `:font-entity` mint pointer, so it stays (the
/// ledger's Decisions records why this one is not ARC's).
fileprivate func macfont_free_entity(_ entity: Lisp_Object) {
  let val = assq_no_quit(QCfont_entity(), AREF(entity, FONT_EXTRA_INDEX()))
  let name = xmint_pointer(XCAR(XCDR(val)))

  block_input()
  Unmanaged<CFString>.fromOpaque(name!).release()
  unblock_input()
}

/// C: `macfont_has_char` (src/macfont.m 2849-2876).
fileprivate func macfont_has_char(_ font: Lisp_Object, _ c: Int32) -> Int32 {
  var result: Int32
  var charset: CFCharacterSet?

  if c < 0 || c > Int32(MAX_UNICODE_CHAR()) {
    return 0
  }

  block_input()
  if FONT_ENTITY_P(font) {
    var val: Lisp_Object

    val = assq_no_quit(QCfont_entity(), AREF(font, FONT_EXTRA_INDEX()))
    val = XCDR(val)
    let name = xmint_pointer(XCAR(val))
    charset = macfont_get_cf_charset_for_name(
      Unmanaged<CFString>.fromOpaque(name!).takeUnretainedValue())
  } else {
    charset = macfont_get_cf_charset(XFONT_OBJECT(font))
  }

  result = Int32(CFCharacterSetIsLongCharacterMember(charset, UInt32(c)) ? 1 : 0)
  unblock_input()

  return result
}

/// C: `macfont_encode_char` (src/macfont.m 2878-2888).
fileprivate func macfont_encode_char(_ font: UnsafeMutablePointer<font>?, _ c: Int32) -> UInt32 {
  var glyph: CGGlyph

  block_input()
  glyph = macfont_get_glyph_for_character(font, UTF32Char(c))
  unblock_input()

  return glyph != kCGFontIndexInvalid ? UInt32(glyph) : FONT_INVALID_CODE()
}

/// C: `mac_font_equal_in_postscript_name` (src/macfont.m 3750-3773).  C's two `CFRelease`s are
/// ARC's here (both are `Copy` results).
fileprivate func mac_font_equal_in_postscript_name(_ font1: CTFont?, _ font2: CTFont?) -> Bool {
  if font1 === font2 {
    return true
  }

  var result = false
  let name1: CFString? = CTFontCopyPostScriptName(font1!)

  if name1 != nil {
    let name2: CFString? = CTFontCopyPostScriptName(font2!)

    if name2 != nil {
      result = CFEqual(name1, name2)
    }
  }

  return result
}


