  var regexp: Lisp_Object = nil
  var i: Int = 0
  var j: Int = 0

  return withUnsafeTemporaryAllocation(of: CChar.self, capacity: n * 2 + 1) { re in
    j = 0
    i = 0
    while i < n {
      if str[i] == CChar(46) /* '.' */ {
        re[j] = CChar(92) /* backslash */
        j += 1
      } else if str[i] == CChar(42) /* '*' */ {
        re[j] = CChar(46) /* '.' */
        j += 1
      }
      re[j] = str[i]
      if re[j] == CChar(63) /* '?' */ {
        re[j] = CChar(46) /* '.' */
      }
      i += 1
      j += 1
    }
    re[j] = 0
    regexp = make_unibyte_string(re.baseAddress, j)

    i = 0
    while cf_charset_table[i].name != nil {
      let name = cf_charset_table[i].name!

      if fast_c_string_match_ignore_case(regexp, name, strlen(name)) >= 0 {
        break
      }
      i += 1
    }
    if cf_charset_table[i].name == nil {
      return -1
    }
    if cf_charset_table[i].cf_charset == nil {
      var unichars = [UniChar](repeating: 0, count: 6)
      var count: CFIndex = 0
      let charset = CFCharacterSetCreateMutable(nil)

      if charset == nil {
        return -1
      }
      j = 0
      while uniquifier_at(i, j) != 0 {
        count += macfont_store_utf32char_to_unichars(uniquifier_at(i, j), &unichars)
        CFCharacterSetAddCharactersInRange(charset,
                                          CFRangeMake(CFIndex(uniquifier_at(i, j)), 1))
        j += 1
      }

      let string: CFString? = unichars.withUnsafeBufferPointer { u in
        CFStringCreateWithCharacters(nil, u.baseAddress, count)
      }

      if string == nil {
        return -1
      }
      cf_charset_table[i].cf_charset = CFCharacterSetCreateCopy(nil, charset)
      /* CFCharacterSetCreateWithCharactersInString does not handle
         surrogate pairs properly as of Mac OS X 10.5.  */
      cf_charset_table[i].cf_charset_string = string
    }
    return Int32(i)
  }
}

/// C's `cf_charset_table[i].uniquifier[j]` (src/macfont.m 1829-1835) - the 6-slot array of the
/// table's anonymous struct, which the port mirrors as a tuple.
fileprivate func uniquifier_at(_ i: Int, _ j: Int) -> UTF32Char {
  let u = cf_charset_table[i].uniquifier
  let slots: [Int32] = [u.0, u.1, u.2, u.3, u.4, u.5]

  return UTF32Char(bitPattern: slots[j])
}


// ==========================================================================
// Segment 2 (rc 3.190's order): the OpenType layer and the two spec entry points.
// ==========================================================================

/// C: `macfont_create_attributes_with_spec`'s local anonymous struct (src/macfont.m 1962-1993) -
/// the file's own type, never crossing the ABI; a Swift struct like `macfont_numeric_trait`.
/// Its `CGPoint` members are C's `{trait value, style value}` pairs and the walk below reads the
/// **second** field as C does - the mirror of the other table, whose walk reads the first.
fileprivate struct macfont_spec_numeric_trait {
  var index: Int
  var trait: CFString
  var points: [CGPoint]
}

/// C: `macfont_get_open_type_spec` (src/macfont.m 1885-1949).  The `malloc`/`free` here are
/// libc's, not this lane's `xmalloc`/`xfree`: C tolerates allocation failure and answers NULL.
/// C's `min (PTRDIFF_MAX, SIZE_MAX) / sizeof (int) < len` bound is `Int.max /
/// sizeof (UInt32) < len` on this target (PTRDIFF_MAX is the smaller of the two).
fileprivate func macfont_get_open_type_spec(_ otf_spec_in: Lisp_Object)
  -> UnsafeMutablePointer<OpenTypeSpec>? {
  let raw = xmalloc(MemoryLayout<OpenTypeSpec>.size)

  if raw == nil {
    return nil
  }
  let spec = raw!.assumingMemoryBound(to: OpenTypeSpec.self)
  var otf_spec = otf_spec_in
  var val: Lisp_Object
  var i = 0
  var j = 0
  var negative = false

  spec.pointee.script = XCAR(otf_spec)
  if !NILP(spec.pointee.script) {
    spec.pointee.script_tag = OTF_SYM_TAG(spec.pointee.script)
    val = assq_no_quit(spec.pointee.script, Votf_script_alist)
    if CONSP(val) && SYMBOLP(XCDR(val)) {
      spec.pointee.script = XCDR(val)
    } else {
      spec.pointee.script = Qnil()
    }
  } else {
    spec.pointee.script_tag = 0x44464C54  /* "DFLT" */
  }
  otf_spec = XCDR(otf_spec)
  spec.pointee.langsys_tag = 0
  if !NILP(otf_spec) {
    val = XCAR(otf_spec)
    if !NILP(val) {
      spec.pointee.langsys_tag = OTF_SYM_TAG(val)
    }
    otf_spec = XCDR(otf_spec)
  }
  set_otspec_nfeatures(spec, 0, 0)
  set_otspec_nfeatures(spec, 1, 0)
  while i < 2 && !NILP(otf_spec) {
    val = XCAR(otf_spec)
    if NILP(val) {
      i += 1
      otf_spec = XCDR(otf_spec)
      continue
    }
    let len = list_length(val)

    set_otspec_features(spec, i,
                        Int.max / MemoryLayout<UInt32>.size < len
                          ? nil
                          : malloc(len * MemoryLayout<UInt32>.size)?
                              .assumingMemoryBound(to: UInt32.self))
    if otspec_features(spec, i) == nil {
      if i > 0 && otspec_features(spec, 0) != nil {
        free(otspec_features(spec, 0)!)
      }
      free(spec)
      return nil
    }
    j = 0
    negative = false
    while CONSP(val) {
      if NILP(XCAR(val)) {
        negative = true
      } else {
        let tag = OTF_SYM_TAG(XCAR(val))

        otspec_features(spec, i)![j] = negative ? (tag | 0x80000000) : tag
        j += 1
      }
      val = XCDR(val)
    }
    set_otspec_nfeatures(spec, i, Int32(j))
    i += 1
    otf_spec = XCDR(otf_spec)
  }

  return spec
}

/// C: `macfont_create_attributes_with_spec` (src/macfont.m 1951-2186).  C's `goto err` is the
/// labelled `do` with `break err` the file uses elsewhere (the `err` arm drops `attributes` and
/// falls into the same `finish` tail, which is why both leave through the same `return`); every
/// `CFRelease` is ARC's - including the `charset`/`charset_string` pair C releases only when
/// `cf_charset_idx < 0` (there they are this function's own `Create` results, while the table's
/// pair is owned by the table).
fileprivate func macfont_create_attributes_with_spec(_ spec: Lisp_Object)
  -> CFMutableDictionary? {
  var tmp: Lisp_Object
  var extra: Lisp_Object
  var langarray: CFMutableArray? = nil
  var charset: CFCharacterSet? = nil
  var charset_string: CFString? = nil
  var attributes: CFMutableDictionary? = nil
  var traits: CFMutableDictionary? = nil
  var script: Lisp_Object = Qnil()
  var registry: Lisp_Object
  var cf_charset_idx: Int32
  var otspec: UnsafeMutablePointer<OpenTypeSpec>? = nil
  let numeric_traits: [macfont_spec_numeric_trait] = [
    macfont_spec_numeric_trait(index: FONT_WEIGHT_INDEX(), trait: kCTFontWeightTrait, points: [
      /* thin */
      CGPoint(x: -0.6, y: 0),
      /* ultra-light, ultralight, extra-light, extralight  */
      CGPoint(x: -0.4, y: 40),
      /* light */
      CGPoint(x: -0.23, y: 50),
      /* semi-light, semilight, demilight */
      CGPoint(x: -0.115, y: 55),
      /* regular, normal, unspecified, book */
      CGPoint(x: 0, y: 80),
      /* medium */
      CGPoint(x: 0.2, y: 100),
      /* semi-bold, semibold, demibold, demi-bold, demi */
      CGPoint(x: 0.3, y: 180),
      /* bold */
      CGPoint(x: 0.4, y: 200),
      /* extra-bold, extrabold, ultra-bold, ultrabold */
      CGPoint(x: 0.6, y: 205),
      /* black, heavy */
      CGPoint(x: 0.8, y: 210),
      /* ultra-heavy, ultraheavy */
      CGPoint(x: 1, y: 250),
      CGPoint(x: CGFloat.greatestFiniteMagnitude, y: CGFloat.greatestFiniteMagnitude),
    ]),
    macfont_spec_numeric_trait(index: FONT_SLANT_INDEX(), trait: kCTFontSlantTrait, points: [
      CGPoint(x: 0, y: 100), CGPoint(x: 0.1, y: 200),
      CGPoint(x: CGFloat.greatestFiniteMagnitude, y: CGFloat.greatestFiniteMagnitude),
    ]),
    macfont_spec_numeric_trait(index: FONT_WIDTH_INDEX(), trait: kCTFontWidthTrait, points: [
      /* ultra-condensed, ultracondensed */
      CGPoint(x: -0.4, y: 50),
      /* extra-condensed, extracondensed */
      CGPoint(x: -0.3, y: 63),
      /* condensed, compressed, narrow */
      CGPoint(x: -0.2, y: 75),
      /* semi-condensed, semicondensed, demicondensed */
      CGPoint(x: -0.1, y: 87),
      /* normal, medium, regular, unspecified */
      CGPoint(x: 0, y: 100),
      /* semi-expanded, semiexpanded, demiexpanded */
      CGPoint(x: 0.1, y: 113),
      /* expanded */
      CGPoint(x: 0.2, y: 125),
      /* extra-expanded, extraexpanded */
      CGPoint(x: 0.3, y: 150),
      /* ultra-expanded, ultraexpanded, wide */
      CGPoint(x: 0.4, y: 200),
      CGPoint(x: CGFloat.greatestFiniteMagnitude, y: CGFloat.greatestFiniteMagnitude),
    ])
    // C's `points` is a fixed `CGPoint points[12]` whose unused entries are zero-filled; the walk
    // below can never reach them (the `CGFLOAT_MAX` row stops it), so the port lists the
    // reference's own entries as the other table's port does.
  ]

  err: do {
    registry = AREF(spec, FONT_REGISTRY_INDEX())
    if NILP(registry)
        || EQ(registry, Qascii_0())
        || EQ(registry, Qiso10646_1())
        || EQ(registry, Qunicode_bmp()) {
      cf_charset_idx = -1
    } else {
      cf_charset_idx = macfont_get_charset(registry)
      if cf_charset_idx < 0 {
        break err
      }
      charset = cf_charset_table[Int(cf_charset_idx)].cf_charset
      charset_string = cf_charset_table[Int(cf_charset_idx)].cf_charset_string
      let lang = cf_charset_table[Int(cf_charset_idx)].lang

      if lang != nil {
        langarray = withUnsafePointer(to: kCFTypeArrayCallBacks) { callbacks in
          CFArrayCreateMutable(nil, 0, callbacks)
        }
        if langarray == nil {
          break err
        }
        CFArrayAppendValue(langarray,
                           UnsafeRawPointer(Unmanaged.passUnretained(lang!).toOpaque()))
      }
    }

    extra = AREF(spec, FONT_EXTRA_INDEX())
    while CONSP(extra) {
      var key: Lisp_Object
      var val: Lisp_Object

      tmp = XCAR(extra)
      key = XCAR(tmp)
      val = XCDR(tmp)
      if EQ(key, QClang()) {
        if langarray == nil {
          langarray = withUnsafePointer(to: kCFTypeArrayCallBacks) { callbacks in
            CFArrayCreateMutable(nil, 0, callbacks)
          }
        }
        if langarray == nil {
          break err
        }
        if SYMBOLP(val) {
          val = Fcons(val, Qnil())
        }
        while CONSP(val) {
          if SYMBOLP(XCAR(val)) {
            let lang = cfstring_create_with_string_noencode(SYMBOL_NAME(XCAR(val)))

            if lang == nil {
              break err
            }
            CFArrayAppendValue(langarray,
                               UnsafeRawPointer(Unmanaged.passUnretained(lang!).toOpaque()))
          }
          val = XCDR(val)
        }
      } else if EQ(key, QCotf()) {
        otspec = macfont_get_open_type_spec(val)
        if otspec == nil {
          break err
        }
        script = otspec!.pointee.script
      } else if EQ(key, QCscript()) {
        script = val
      }
      extra = XCDR(extra)
    }

    if !NILP(script) && charset == nil {
      var chars = assq_no_quit(script, Vscript_representative_chars)

      if CONSP(chars) && CONSP(CDR(chars)) {
        let string = CFStringCreateMutable(nil, 0)
        let cs = CFCharacterSetCreateMutable(nil)

        if string == nil || cs == nil {
          break err
        }
        chars = XCDR(chars)
        while CONSP(chars) {
          if CHARACTERP(XCAR(chars)) {
            var unichars = [unichar](repeating: 0, count: 2)
            let count = macfont_store_utf32char_to_unichars(UTF32Char(XFIXNAT(XCAR(chars))), &unichars)
            let range = CFRangeMake(XFIXNAT(XCAR(chars)), 1)

            CFStringAppendCharacters(string, &unichars, count)
            CFCharacterSetAddCharactersInRange(cs, range)
          }
          chars = XCDR(chars)
        }
        charset = cs
        /* CFCharacterSetCreateWithCharactersInString does not handle surrogate pairs
           properly as of Mac OS X 10.5.  */
        charset_string = string
      }
    }

    attributes = withUnsafePointer(to: kCFTypeDictionaryKeyCallBacks) { keys in
      withUnsafePointer(to: kCFTypeDictionaryValueCallBacks) { values in
        CFDictionaryCreateMutable(nil, 0, keys, values)
      }
    }
    if attributes == nil {
      break err
    }

    tmp = AREF(spec, FONT_FAMILY_INDEX())
    if SYMBOLP(tmp) && !NILP(tmp) {
      let family = macfont_create_family_with_symbol(tmp)

      if family == nil {
        break err
      }
      CFDictionaryAddValue(attributes,
                           UnsafeRawPointer(Unmanaged
                             .passUnretained(kCTFontFamilyNameAttribute).toOpaque()),
                           UnsafeRawPointer(Unmanaged.passUnretained(family!).toOpaque()))
    }

    traits = withUnsafePointer(to: kCFTypeDictionaryKeyCallBacks) { keys in
      withUnsafePointer(to: kCFTypeDictionaryValueCallBacks) { values in
        CFDictionaryCreateMutable(nil, 4, keys, values)
      }
    }
    if traits == nil {
      break err
    }

    for i in 0..<numeric_traits.count {
      tmp = AREF(spec, numeric_traits[i].index)
      if FIXNUMP(tmp) {
        var floatval = CGFloat(XFIXNUM(tmp) >> 8)  // XXX
        let points = numeric_traits[i].points
        var point = 0

        while points[point].y < floatval {
          point += 1
        }
        if point == 0 {
          point += 1
        } else if points[point].y == CGFloat.greatestFiniteMagnitude {
          point -= 1
        }
        floatval = points[point - 1].x + ((floatval - points[point - 1].y)
                                          * ((points[point].x - points[point - 1].x)
                                             / (points[point].y - points[point - 1].y)))
        if floatval > 1.0 {
          floatval = 1.0
        } else if floatval < -1.0 {
          floatval = -1.0
        }
        let num = CFNumberCreate(nil, CFNumberType.cgFloatType, &floatval)

        if num == nil {
          break err
        }
        CFDictionaryAddValue(traits,
                             UnsafeRawPointer(Unmanaged
                               .passUnretained(numeric_traits[i].trait).toOpaque()),
                             UnsafeRawPointer(Unmanaged.passUnretained(num!).toOpaque()))
      }
    }
    if CFDictionaryGetCount(traits) > 0 {
      CFDictionaryAddValue(attributes,
                           UnsafeRawPointer(Unmanaged
                             .passUnretained(kCTFontTraitsAttribute).toOpaque()),
                           UnsafeRawPointer(Unmanaged.passUnretained(traits!).toOpaque()))
    }

    if charset != nil {
      CFDictionaryAddValue(attributes,
                           UnsafeRawPointer(Unmanaged
                             .passUnretained(kCTFontCharacterSetAttribute).toOpaque()),
                           UnsafeRawPointer(Unmanaged.passUnretained(charset!).toOpaque()))
    }
    if charset_string != nil {
      CFDictionaryAddValue(attributes,
                           UnsafeRawPointer(Unmanaged
                             .passUnretained(MAC_FONT_CHARACTER_SET_STRING_ATTRIBUTE).toOpaque()),
                           UnsafeRawPointer(Unmanaged
                             .passUnretained(charset_string!).toOpaque()))
    }
    if langarray != nil {
      CFDictionaryAddValue(attributes,
                           UnsafeRawPointer(Unmanaged
                             .passUnretained(kCTFontLanguagesAttribute).toOpaque()),
                           UnsafeRawPointer(Unmanaged.passUnretained(langarray!).toOpaque()))
    }
  }

  return attributes
}

/// C: `macfont_supports_charset_and_languages_p` (src/macfont.m 2190-2227).  C's `CFRelease
/// (desc_charset)` is ARC's (a `Copy` result).
fileprivate func macfont_supports_charset_and_languages_p(_ desc: CTFontDescriptor?,
                                                          _ charset: CFCharacterSet?,
                                                          _ chars: Lisp_Object,
                                                          _ languages: CFArray?) -> Bool {
  var result = true

  if charset != nil || VECTORP(chars) {
    let desc_charset = CTFontDescriptorCopyAttribute(desc!, kCTFontCharacterSetAttribute)

    if desc_charset == nil {
      result = false
    } else {
      let descCharset = desc_charset as! CFCharacterSet

      if charset != nil {
        result = CFCharacterSetIsSupersetOfSet(descCharset, charset)
      } else {
        /* VECTORP (chars) */
        var j = 0

        while j < ASIZE(chars) {
          if RANGED_FIXNUMP(0, AREF(chars, j), Int(MAX_UNICODE_CHAR()))
              && CFCharacterSetIsLongCharacterMember(descCharset,
                                                     UInt32(XFIXNAT(AREF(chars, j)))) {
            break
          }
          j += 1
        }
        if j == ASIZE(chars) {
          result = false
        }
      }
    }
  }
  if result && languages != nil {
    result = mac_font_descriptor_supports_languages(desc, languages)
  }

  return result
}

/// C: `macfont_list` (src/macfont.m 2275-2593).  C's `goto finish`/`goto err` are the labelled
/// `do` with `break body` the file uses elsewhere (the `err` arm drops `val` back to `Qnil`
/// first), and every `CFRetain`/`CFRelease` is ARC's - including the `CFRelease (families)` C
/// runs only on the success path (C leaks it on the `err` path; Swift owns it either way).
fileprivate func macfont_list(_ f: UnsafeMutableRawPointer?, _ spec: Lisp_Object) -> Lisp_Object {
  var val: Lisp_Object = Qnil()
  var family: Lisp_Object
  var extra: Lisp_Object
  var family_name: CFString? = nil
  var attributes: CFMutableDictionary? = nil
  var traits: CFMutableDictionary? = nil
  var chars: Lisp_Object = Qnil()
  var spacing: Int32 = -1
  var synth_sym_traits: CTFontSymbolicTraits = []
  var families: CFArray? = nil
  var families_count: CFIndex = 0
  var charset: CFCharacterSet? = nil
  var languages: CFArray? = nil
  var n: Int32

  block_input()

  body: do {
    family = AREF(spec, FONT_FAMILY_INDEX())
    if !NILP(family) {
      family_name = macfont_create_family_with_symbol(family)
      if family_name == nil {
        break body
      }
    }

    attributes = macfont_create_attributes_with_spec(spec)
    if attributes == nil {
      break body
    }

    let languages_ptr = CFDictionaryGetValue(attributes!,
                                             UnsafeRawPointer(Unmanaged
                                               .passUnretained(kCTFontLanguagesAttribute)
                                               .toOpaque()))
    if languages_ptr != nil {
      languages = Unmanaged<CFArray>.fromOpaque(languages_ptr!).takeUnretainedValue()
    }

    if FIXNUMP(AREF(spec, FONT_SPACING_INDEX())) {
      spacing = Int32(truncatingIfNeeded: XFIXNUM(AREF(spec, FONT_SPACING_INDEX())))
    }

    let traits_ptr = CFDictionaryGetValue(attributes!,
                                          UnsafeRawPointer(Unmanaged
                                            .passUnretained(kCTFontTraitsAttribute).toOpaque()))
    if traits_ptr != nil {
      traits = Unmanaged<CFMutableDictionary>.fromOpaque(traits_ptr!).takeUnretainedValue()
    }

    n = FONT_SLANT_NUMERIC(spec)
    if n < 0 || n == FONT_SLANT_SYNTHETIC_ITALIC {
      synth_sym_traits.insert(CTFontSymbolicTraits.traitItalic)
      if traits != nil {
        CFDictionaryRemoveValue(traits!,
                                UnsafeRawPointer(Unmanaged
                                  .passUnretained(kCTFontSlantTrait).toOpaque()))
      }
    }

    n = FONT_WEIGHT_NUMERIC(spec)
    if n < 0 || n == FONT_WEIGHT_SYNTHETIC_BOLD {
      synth_sym_traits.insert(CTFontSymbolicTraits.traitBold)
      if traits != nil {
        CFDictionaryRemoveValue(traits!,
                                UnsafeRawPointer(Unmanaged
                                  .passUnretained(kCTFontWeightTrait).toOpaque()))
      }
    }

    if languages != nil && (spacing < 0 || spacing == Int32(FONT_SPACING_SYNTHETIC_MONO)) {
      let language = Unmanaged<CFString>.fromOpaque(
        CFArrayGetValueAtIndex(languages, 0)!).takeUnretainedValue()

      if CFStringHasPrefix(language, "ja" as CFString)
          || CFStringHasPrefix(language, "ko" as CFString)
          || CFStringHasPrefix(language, "zh" as CFString) {
        synth_sym_traits.insert(CTFontSymbolicTraits.traitMonoSpace)
      }
    }

    /* Create array of families.  */
    if family_name != nil {
      families = withUnsafePointer(to: family_name!) { valuePtr in
        withUnsafePointer(to: kCFTypeArrayCallBacks) { callbacks in
          CFArrayCreate(nil,
                        UnsafeMutablePointer(mutating: UnsafeRawPointer(valuePtr)
                          .assumingMemoryBound(to: UnsafeRawPointer?.self)),
                        1, callbacks)
        }
      }
    } else {
      var pref_family_index: CFIndex = -1

      families = macfont_copy_available_families_cache()
      if families == nil {
        val = Qnil()
        break body
      }

      families_count = CFArrayGetCount(families)

      /* Move preferred family to the front if exists.  */
      let pref_family = mac_font_create_preferred_family_for_attributes(attributes! as CFDictionary)

      if pref_family != nil {
        pref_family_index =
          CFArrayGetFirstIndexOfValue(families,
                                      CFRangeMake(0, families_count),
                                      UnsafeRawPointer(Unmanaged.passUnretained(pref_family!)
                                        .toOpaque()))
      }
      if pref_family_index > 0 {
        let mutable_families = withUnsafePointer(to: kCFTypeArrayCallBacks) {
          callbacks in
          CFArrayCreateMutable(nil, families_count, callbacks)
        }

        if mutable_families != nil {
          CFArrayAppendValue(mutable_families,
                             CFArrayGetValueAtIndex(families, pref_family_index))
          CFArrayAppendArray(mutable_families, families, CFRangeMake(0, pref_family_index))
          if pref_family_index + 1 < families_count {
            CFArrayAppendArray(mutable_families, families,
                               CFRangeMake(pref_family_index + 1,
                                           families_count - (pref_family_index + 1)))
          }
          families = mutable_families
        }
      }
    }

    let charset_ptr = CFDictionaryGetValue(attributes!,
                                           UnsafeRawPointer(Unmanaged
                                             .passUnretained(kCTFontCharacterSetAttribute)
                                             .toOpaque()))
    if charset_ptr != nil {
      charset = Unmanaged<CFCharacterSet>.fromOpaque(charset_ptr!).takeUnretainedValue()
      CFDictionaryRemoveValue(attributes!,
                              UnsafeRawPointer(Unmanaged
                                .passUnretained(kCTFontCharacterSetAttribute).toOpaque()))
    } else {
      val = assq_no_quit(QCscript(), AREF(spec, FONT_EXTRA_INDEX()))
      if !NILP(val) {
        val = assq_no_quit(XCDR(val), Vscript_representative_chars)
        if CONSP(val) && VECTORP(XCDR(val)) {
          chars = XCDR(val)
        }
      }
      val = Qnil()
    }

    if languages != nil {
      CFDictionaryRemoveValue(attributes!,
                              UnsafeRawPointer(Unmanaged
                                .passUnretained(kCTFontLanguagesAttribute).toOpaque()))
    }

    val = Qnil()
    extra = AREF(spec, FONT_EXTRA_INDEX())
    families_count = CFArrayGetCount(families)
    var i = 0
    while i < families_count {
      let family_name = Unmanaged<CFString>.fromOpaque(
        CFArrayGetValueAtIndex(families, i)!).takeUnretainedValue()
      var pat_desc: CTFontDescriptor?
      var descs: CFArray?
      var descs_count: CFIndex
      var filtered_descs: CFMutableArray?
      var traits_array: CFMutableArray?
      var entity: Lisp_Object

      CFDictionarySetValue(attributes,
                           UnsafeRawPointer(Unmanaged
                             .passUnretained(kCTFontFamilyNameAttribute).toOpaque()),
                           UnsafeRawPointer(Unmanaged.passUnretained(family_name).toOpaque()))
      pat_desc = CTFontDescriptorCreateWithAttributes(attributes! as CFDictionary)
      if pat_desc == nil {
        val = Qnil()
        break body
      }

      /* CTFontDescriptorCreateMatchingFontDescriptors on Mac OS X 10.7 returns NULL if
         pat_desc represents the LastResort font.  So we use
         CTFontDescriptorCreateMatchingFontDescriptor (no trailing "s") for such a font.  */
      if !CFEqual(family_name, "LastResort" as CFString) {
        descs = CTFontDescriptorCreateMatchingFontDescriptors(pat_desc!, nil)
      } else {
        let lr_desc = CTFontDescriptorCreateMatchingFontDescriptor(pat_desc!, nil)

        if lr_desc != nil {
          descs = withUnsafePointer(to: lr_desc!) { valuePtr in
            withUnsafePointer(to: kCFTypeArrayCallBacks) { callbacks in
              CFArrayCreate(nil,
                            UnsafeMutablePointer(mutating: UnsafeRawPointer(valuePtr)
                              .assumingMemoryBound(to: UnsafeRawPointer?.self)),
                            1, callbacks)
            }
          }
        } else {
          descs = nil
        }
      }
      if descs == nil {
        i += 1
        continue
      }

      descs_count = CFArrayGetCount(descs)
      if descs_count == 0
          || !macfont_supports_charset_and_languages_p(
              Unmanaged<CTFontDescriptor>.fromOpaque(CFArrayGetValueAtIndex(descs, 0)!)
                .takeUnretainedValue(), charset, chars, languages) {
        i += 1
        continue
      }

      filtered_descs = withUnsafePointer(to: kCFTypeArrayCallBacks) { callbacks in
        CFArrayCreateMutable(nil, descs_count, callbacks)
      }
      traits_array = CFArrayCreateMutable(nil, descs_count, nil)
      var j = 0
      while j < descs_count {
        let desc = Unmanaged<CTFontDescriptor>.fromOpaque(
          CFArrayGetValueAtIndex(descs, j)!).takeUnretainedValue()
        let dict = CTFontDescriptorCopyAttribute(desc, kCTFontTraitsAttribute)
        var sym_traits: CTFontSymbolicTraits = []
        var num: UnsafeRawPointer?

        if dict == nil {
          j += 1
          continue
        }
        let dictCF = dict as! CFDictionary

        num = CFDictionaryGetValue(dictCF,
                                   UnsafeRawPointer(Unmanaged
                                     .passUnretained(kCTFontSymbolicTrait).toOpaque()))
        if num == nil
            || !cfnumber_get_font_symbolic_traits_value(
                Unmanaged<CFNumber>.fromOpaque(num!).takeUnretainedValue(), &sym_traits) {
          j += 1
          continue
        }

        if spacing >= 0
            && !synth_sym_traits.contains(CTFontSymbolicTraits.traitMonoSpace)
            && (sym_traits.contains(CTFontSymbolicTraits.traitMonoSpace)
                != (spacing >= Int32(FONT_SPACING_MONO()))) {
          j += 1
          continue
        }

        /* Don't use a color bitmap font unless its family is explicitly specified or we're
           looking for a font for emoji.  */
        if sym_traits.contains(CTFontSymbolicTraits.traitColorGlyphs)
            && NILP(family)
            && !EQ(CDR_SAFE(assq_no_quit(QCscript(), AREF(spec, FONT_EXTRA_INDEX()))),
                   Qemoji()) {
          j += 1
          continue
        }

        if j > 0
            && !macfont_supports_charset_and_languages_p(desc, charset, chars, languages) {
          j += 1
          continue
        }

        CFArrayAppendValue(filtered_descs,
                           UnsafeRawPointer(Unmanaged.passUnretained(desc).toOpaque()))
        CFArrayAppendValue(traits_array,
                           UnsafeRawPointer(bitPattern: UInt(sym_traits.rawValue)))
        j += 1
      }

      descs = filtered_descs
      descs_count = CFArrayGetCount(descs)

      j = 0
      while j < descs_count {
        let desc = Unmanaged<CTFontDescriptor>.fromOpaque(
          CFArrayGetValueAtIndex(descs, j)!).takeUnretainedValue()
        let sym_traits = CTFontSymbolicTraits(rawValue: UInt32(truncatingIfNeeded:
          UInt(bitPattern: CFArrayGetValueAtIndex(traits_array, j))))
        var mask_min: CTFontSymbolicTraits
        var mask_max: CTFontSymbolicTraits

        mask_min = synth_sym_traits.symmetricDifference(sym_traits).intersection(
          CTFontSymbolicTraits.traitItalic.union(CTFontSymbolicTraits.traitBold))
        if FONT_SLANT_NUMERIC(spec) < 0 {
          mask_min.subtract(CTFontSymbolicTraits.traitItalic)
        }
        if FONT_WEIGHT_NUMERIC(spec) < 0 {
          mask_min.subtract(CTFontSymbolicTraits.traitBold)
        }

        mask_max = synth_sym_traits.subtracting(sym_traits)
        /* Synthetic bold does not work for bitmap-only fonts on Mac OS X 10.6.  */
        if !(mask_min.symmetricDifference(mask_max)
              .intersection(CTFontSymbolicTraits.traitBold)).isEmpty {
          let format = CTFontDescriptorCopyAttribute(desc, kCTFontFormatAttribute)

          if format != nil {
            var format_val: UInt32 = 0
            let formatNum = format as! CFNumber

            if CFNumberGetValue(formatNum, CFNumberType.sInt32Type, &format_val)
                && format_val == CTFontFormat.bitmap.rawValue {
              mask_max.subtract(CTFontSymbolicTraits.traitBold)
            }
          }
        }
        if spacing >= 0 {
          mask_min.formUnion(mask_max.intersection(CTFontSymbolicTraits.traitMonoSpace))
        }

        var mmask = mask_min.intersection(CTFontSymbolicTraits.traitMonoSpace).rawValue
        let mono_max = mask_max.intersection(CTFontSymbolicTraits.traitMonoSpace).rawValue
        while mmask <= mono_max {
          var bmask = mask_min.intersection(CTFontSymbolicTraits.traitBold).rawValue
          let bold_max = mask_max.intersection(CTFontSymbolicTraits.traitBold).rawValue
          while bmask <= bold_max {
            var imask = mask_min.intersection(CTFontSymbolicTraits.traitItalic).rawValue
            let italic_max = mask_max.intersection(CTFontSymbolicTraits.traitItalic).rawValue
            while imask <= italic_max {
              let synth = CTFontSymbolicTraits(rawValue: imask | bmask | mmask)

              if synth.isEmpty
                  || macfont_closest_traits_index_p(traits_array, sym_traits.union(synth), j) {
                entity = macfont_descriptor_entity(desc, extra, synth)
                if !NILP(entity) {
                  val = Fcons(entity, val)
                }
              }
              imask += CTFontSymbolicTraits.traitItalic.rawValue
            }
            bmask += CTFontSymbolicTraits.traitBold.rawValue
          }
          mmask += CTFontSymbolicTraits.traitMonoSpace.rawValue
        }
        j += 1
      }
      i += 1
    }

    val = Fnreverse(val)
  }

  "macfont-list".withCString { FONT_ADD_LOG($0, spec, val) }
  unblock_input()

  return val
}

/// C: `macfont_match` (src/macfont.m 2595-2621).  C's `CFRelease`s are ARC's (`Create`/`Copy`
/// results), and the unused `frame` parameter is kept as C declares it.
fileprivate func macfont_match(_ frame: UnsafeMutableRawPointer?, _ spec: Lisp_Object)
  -> Lisp_Object {
  var entity: Lisp_Object = Qnil()
  var attributes: CFMutableDictionary?
  var pat_desc: CTFontDescriptor? = nil
  var desc: CTFontDescriptor? = nil

  block_input()

  attributes = macfont_create_attributes_with_spec(spec)
  if attributes != nil {
    pat_desc = CTFontDescriptorCreateWithAttributes(attributes! as CFDictionary)
  }
  if pat_desc != nil {
    desc = CTFontDescriptorCreateMatchingFontDescriptor(pat_desc!, nil)
  }
  if desc != nil {
    entity = macfont_descriptor_entity(desc, AREF(spec, FONT_EXTRA_INDEX()),
                                       CTFontSymbolicTraits(rawValue: 0))
  }
  unblock_input()

  "macfont-match".withCString { FONT_ADD_LOG($0, spec, entity) }

  return entity
}

// ==========================================================================
// Segment 3a (rc 3.190's cut): the rest of the driver core's entry points.
// ==========================================================================

/// C: `font->driver = &macfont_driver;` (src/macfont.m 2701) and
/// `register_font_driver (&macfont_driver, f);` (4217) read this file's own `macfont_driver`
/// (1765-1791).  That record is a C **data symbol**, which Swift cannot emit, so the lane
/// exports it as a getter **of its own C name** (rc 3.166, decision 2; the shape
/// `nsfont.swift`'s `nsfont_driver` entry has) and both sites become calls to that entry -
/// the Rust side writes its own `&macfont_driver` the same way.  The record and the getter
/// land in the closure round (the record's initialiser names `macfont_shape`), so until then
/// this is an undefined `_macfont_driver` in `nm -u`, exactly as C's forward reference is
/// unresolved until the record's definition below it.
@_silgen_name("macfont_driver") func macfont_driver_address() -> UnsafeMutableRawPointer?

/// C: `macfont_list_family` (src/macfont.m 2627-2647).  C's `CFRelease (families)` is ARC's
/// here (the cache read is a strong reference in Swift).
fileprivate func macfont_list_family(_ frame: UnsafeMutableRawPointer?) -> Lisp_Object {
  var list: Lisp_Object = Qnil()

  block_input()

  let families = macfont_copy_available_families_cache()

  if families != nil {
    let count = CFArrayGetCount(families)
    var i: CFIndex = 0

    while i < count {
      list = Fcons(macfont_intern_prop_cfstring(
                     Unmanaged<CFString>.fromOpaque(CFArrayGetValueAtIndex(families, i)!)
                       .takeUnretainedValue()),
                   list)
      i += 1
    }
  }

  unblock_input()

  return list
}

/// C: `macfont_open` (src/macfont.m 2662-2821).  `font_build_object` is the core's own entry
/// (src/font.c 250) and `VECSIZE (struct macfont_info)` is the `VECSIZE` macro over the
/// record's C `sizeof` - 264, which is this mirror's **stride** (`MemoryLayout.size` is 262
/// because Swift's `size` omits the record's trailing padding).  C's `CFRelease (family_name)`
/// is ARC's, and `font->driver = &macfont_driver` is the getter entry declared above.
fileprivate func macfont_open(_ f: UnsafeMutableRawPointer?, _ entity: Lisp_Object,
                              _ pixel_size: Int32) -> Lisp_Object {
  var val: Lisp_Object
  var font_object: Lisp_Object
  var size: Int32
  var sym_traits: CTFontSymbolicTraits
  var macfont: CTFont?
  var glyph: CGGlyph
  var total_width: Int32
  /* C leaves `ascent`/`descent`/`leading` uninitialised and reads them only after the metrics
     call fills them (`mac_screen_font_get_metrics` writes all three on its one return-true
     path, and the `CTFontGet*` arm below assigns all three); Swift requires a local to be
     initialised before `&ascent` may appear in an argument position, so the port gives them the
     record's trivial value.  */
  var ascent: CGFloat = 0, descent: CGFloat = 0, leading: CGFloat = 0

  val = assq_no_quit(QCfont_entity(), AREF(entity, FONT_EXTRA_INDEX()))
  if !CONSP(val)
      || !CONSP(XCDR(val)) {
    return Qnil()
  }
  let font_name = Unmanaged<CFString>.fromOpaque(xmint_pointer(XCAR(XCDR(val)))!)
    .takeUnretainedValue()

  sym_traits = CTFontSymbolicTraits(rawValue: UInt32(truncatingIfNeeded:
    XFIXNUM(XCDR(XCDR(val)))))

  size = Int32(truncatingIfNeeded: XFIXNUM(AREF(entity, FONT_SIZE_INDEX())))
  if size == 0 {
    size = pixel_size
  }

  block_input()
  macfont = CTFontCreateWithName(font_name, CGFloat(size), nil)
  if macfont != nil {
    /* C: `int fontsize = (int) [((NSFont *) macfont) pointSize];` - `CTFont` and `NSFont` are
       toll-free bridged, so the cast is the unwrap (the shape `mac_font_get_weight` uses).  */
    let nsFont: NSFont = macfont!
    let fontsize = Int32(nsFont.pointSize)

    if fontsize != size {
      size = fontsize
    }
  }
  unblock_input()
  if macfont == nil {
    return Qnil()
  }

  font_object = font_build_object(Int32(VECSIZE(MemoryLayout<macfont_info>.stride)), Qmac_ct(),
                                  entity, Double(size))
  let font: UnsafeMutablePointer<font> = XFONT_OBJECT(font_object)!
  font.pointee.pixel_size = size
  font.pointee.driver = UnsafeRawPointer(macfont_driver_address())
  font.pointee.encoding_charset = -1
  font.pointee.repertory_charset = -1
  /* Clear font->space_width so macfont_monospace_width_multiplier may not be confused by an
     uninitialized value.  */
  font.pointee.space_width = 0

  block_input()

  let macfont_info = UnsafeMutableRawPointer(font).assumingMemoryBound(to: macfont_info.self)
  macfont_info.pointee.macfont = macfont
  macfont_info.pointee.cgfont = CTFontCopyGraphicsFont(macfont!, nil)

  val = assq_no_quit(QCdestination(), AREF(entity, FONT_EXTRA_INDEX()))
  if CONSP(val) && BASE_EQ(XCDR(val), make_fixnum(1)) {
    macfont_info.pointee.screen_font =
      mac_screen_font_create_with_name(font_name, CGFloat(size))
  } else {
    macfont_info.pointee.screen_font = nil
  }
  macfont_info.pointee.cache = macfont_lookup_cache(font_name)
  _ = macfont_retain_cache(macfont_info.pointee.cache)
  macfont_info.pointee.metrics = nil
  macfont_info.pointee.metrics_nrows = 0
  set_synthetic_italic_p(macfont_info, false)
  set_synthetic_bold_p(macfont_info, false)
  set_spacing(macfont_info, MACFONT_SPACING_PROPORTIONAL)
  set_antialias(macfont_info, MACFONT_ANTIALIAS_DEFAULT)
  if !sym_traits.contains(CTFontSymbolicTraits.traitItalic)
      && FONT_SLANT_NUMERIC(entity) == FONT_SLANT_SYNTHETIC_ITALIC {
    set_synthetic_italic_p(macfont_info, true)
  }
  if !sym_traits.contains(CTFontSymbolicTraits.traitBold)
      && FONT_WEIGHT_NUMERIC(entity) == FONT_WEIGHT_SYNTHETIC_BOLD {
    set_synthetic_bold_p(macfont_info, true)
  }
  if sym_traits.contains(CTFontSymbolicTraits.traitMonoSpace) {
    set_spacing(macfont_info, MACFONT_SPACING_MONO)
  } else if FIXNUMP(AREF(entity, FONT_SPACING_INDEX()))
      && (XFIXNUM(AREF(entity, FONT_SPACING_INDEX())) == FONT_SPACING_SYNTHETIC_MONO) {
    set_spacing(macfont_info, MACFONT_SPACING_SYNTHETIC_MONO)
  }
  if synthetic_italic_p(macfont_info) || synthetic_bold_p(macfont_info) {
    set_antialias(macfont_info, MACFONT_ANTIALIAS_ON)
  } else {
    val = assq_no_quit(QCantialias(), AREF(entity, FONT_EXTRA_INDEX()))
    if CONSP(val) {
      set_antialias(macfont_info,
                    NILP(XCDR(val)) ? MACFONT_ANTIALIAS_OFF : MACFONT_ANTIALIAS_ON)
    }
  }
  set_color_bitmap_p(macfont_info, false)
  if sym_traits.contains(CTFontSymbolicTraits.traitColorGlyphs) {
    set_color_bitmap_p(macfont_info, true)
  }

  glyph = macfont_get_glyph_for_character(font, UTF32Char(32))
  if glyph != kCGFontIndexInvalid {
    font.pointee.space_width = macfont_glyph_extents(font, glyph, nil, nil, 0)
  } else {
    /* dirty workaround */
    font.pointee.space_width = pixel_size
  }

  total_width = font.pointee.space_width
  var i: Int32 = 1
  while i < 95 {
    glyph = macfont_get_glyph_for_character(font, UTF32Char(32 + i))
    if glyph == kCGFontIndexInvalid {
      break
    }
    total_width += macfont_glyph_extents(font, glyph, nil, nil, 0)
    i += 1
  }
  if i == 95 {
    font.pointee.average_width = total_width / 95
  } else {
    font.pointee.average_width = font.pointee.space_width /* XXX */
  }

  if !(macfont_info.pointee.screen_font != nil
       && mac_screen_font_get_metrics(macfont_info.pointee.screen_font,
                                      &ascent, &descent, &leading)) {
    ascent = CTFontGetAscent(macfont!)
    descent = CTFontGetDescent(macfont!)
    leading = CTFontGetLeading(macfont!)
    /* AppKit and WebKit do some adjustment to the heights of Courier, Helvetica, and
       Times.  C's `if (family_name)` has no Swift spelling (the SDK imports
       `CTFontCopyFamilyName` as a non-optional `CFString`, and NULL comes only from a NULL
       font, which this function has ruled out) - the deviation `CTRunGetAttributes` already
       has here.  */
    let family_name = CTFontCopyFamilyName(macfont!)

    if CFEqual(family_name, "Courier" as CFString)
        || CFEqual(family_name, "Helvetica" as CFString)
        || CFEqual(family_name, "Times" as CFString) {
      ascent += (ascent + descent) * 0.15
    } else if CFStringHasPrefix(family_name, "Hiragino" as CFString) {
      leading *= 0.25
      ascent += leading
    }
  }
  font.pointee.ascent = Int32(ascent + 0.5)
  val = assq_no_quit(QCminspace(), AREF(entity, FONT_EXTRA_INDEX()))
  if CONSP(val) && !NILP(XCDR(val)) {
    font.pointee.descent = Int32(descent + 0.5)
  } else {
    font.pointee.descent = Int32(descent + leading + 0.5)
  }
  font.pointee.height = font.pointee.ascent + font.pointee.descent

  font.pointee.underline_position = Int32(-CTFontGetUnderlinePosition(macfont!) + 0.5)
  font.pointee.underline_thickness = Int32(CTFontGetUnderlineThickness(macfont!) + 0.5)

  unblock_input()

  /* Unfortunately Xft doesn't provide a way to get minimum char width.  So, we use
     space_width instead.  */
  font.pointee.min_width = font.pointee.space_width
  font.pointee.max_width = font.pointee.space_width /* XXX */

  font.pointee.baseline_offset = 0
  font.pointee.relative_compose = 0
  font.pointee.default_ascent = 0
  font.pointee.vertical_centering = false

  return font_object
}

/// C: `macfont_close` (src/macfont.m 2824-2846).  C's `CFRelease (macfont_info->macfont)` and
/// `CGFontRelease (macfont_info->cgfont)` are the ports' `nil` assignments - the reading
/// `macfont_release_cache` records for a mirror record's CF fields (ARC owns the two strong
/// references) - while `screen_font` is a raw +1 pointer (`mac_screen_font_create_with_name`
/// hands one over), so its release stays explicit, as in `macfont_free_entity`.
fileprivate func macfont_close(_ font: UnsafeMutablePointer<font>?) {
  let macfont_info = UnsafeMutableRawPointer(font!).assumingMemoryBound(to: macfont_info.self)

  if macfont_info.pointee.cache != nil {
    block_input()
    macfont_info.pointee.macfont = nil
    macfont_info.pointee.cgfont = nil
    if macfont_info.pointee.screen_font != nil {
      Unmanaged<NSFont>.fromOpaque(macfont_info.pointee.screen_font!).release()
    }
    macfont_release_cache(macfont_info.pointee.cache)
    var i: Int32 = 0
    while i < Int32(macfont_info.pointee.metrics_nrows) {
      if macfont_info.pointee.metrics![Int(i)] != nil {
        xfree(UnsafeMutableRawPointer(macfont_info.pointee.metrics![Int(i)]))
      }
      i += 1
    }
    if macfont_info.pointee.metrics != nil {
      xfree(UnsafeMutableRawPointer(macfont_info.pointee.metrics))
    }
    macfont_info.pointee.cache = nil
    unblock_input()
  }
}

/// C: `macfont_text_extents` (src/macfont.m 2890-2921).  C's `struct font_metrics m;` is an
/// uninitialised local it only reads when `metrics` is non-NULL, in which case the call fills
/// it; the port zero-initialises the record (its trivial value) and keeps C's `metrics ? &m :
/// nil` as the two call sites it is (Swift's `&m` may only appear in an argument position, so
/// the ternary C spells cannot be written and the branch is the if/else).  The `short` fields
/// of `metrics` take C's truncating `int`-to-`short` assignments.
fileprivate func macfont_text_extents(_ font: UnsafeMutablePointer<font>?,
                                      _ code: UnsafePointer<UInt32>?,
                                      _ nglyphs: Int32,
                                      _ metrics: UnsafeMutablePointer<font_metrics>?) {
  var width: Int32
  var i: Int32

  block_input()
  width = macfont_glyph_extents(font, CGGlyph(truncatingIfNeeded: code![0]), metrics, nil, 0)
  i = 1
  while i < nglyphs {
    var m = font_metrics(lbearing: 0, rbearing: 0, width: 0, ascent: 0, descent: 0)
    var w: Int32

    if metrics != nil {
      w = macfont_glyph_extents(font, CGGlyph(truncatingIfNeeded: code![Int(i)]), &m, nil, 0)
    } else {
      w = macfont_glyph_extents(font, CGGlyph(truncatingIfNeeded: code![Int(i)]), nil, nil, 0)
    }

    if metrics != nil {
      if width + Int32(m.lbearing) < Int32(metrics!.pointee.lbearing) {
        metrics!.pointee.lbearing =
          Int16(truncatingIfNeeded: width + Int32(m.lbearing))
      }
      if width + Int32(m.rbearing) > Int32(metrics!.pointee.rbearing) {
        metrics!.pointee.rbearing =
          Int16(truncatingIfNeeded: width + Int32(m.rbearing))
      }
      if m.ascent > metrics!.pointee.ascent {
        metrics!.pointee.ascent = m.ascent
      }
      if m.descent > metrics!.pointee.descent {
        metrics!.pointee.descent = m.descent
      }
    }
    width += w
    i += 1
  }
  unblock_input()

  if metrics != nil {
    metrics!.pointee.width = Int16(truncatingIfNeeded: width)
  }
}


// ==========================================================================
// Segment 3b (rc 3.190's cut): `macfont_shape` and the two CoreText helpers it needs
// (`mac_font_create_line_with_string_and_font` and `mac_font_shape`, both of which C defines
// in the file's own tail at 3775/3839 - the port keeps them with their only caller).
// ==========================================================================

/// C: `macfont_shape` (src/macfont.m 3094-3241).  C's three `alloca` scratch arrays are
/// Swift's `withUnsafeTemporaryAllocation` - the same scoped, stack-first temporary storage the
/// port of src/nsfont.m's `nsfont_shape` uses - nested because each one's lifetime is the rest
/// of the function, and with `max (_, 1)` capacities because C's `alloca (0)` never yields NULL
/// while Swift's zero-capacity buffer has no `baseAddress` to hand to the SDK.  C's
/// `CFRelease (string)` is ARC's, and `CFStringCreateWithCharactersNoCopy` keeps C's
/// `kCFAllocatorNull` (the buffer is the stack scratch, which must not be freed by CF).
fileprivate func macfont_shape(_ lgstring: Lisp_Object, _ direction: Lisp_Object) -> Lisp_Object {
  let font = CHECK_FONT_GET_OBJECT(LGSTRING_FONT(lgstring))!
  let macfont_info = UnsafeMutableRawPointer(font).assumingMemoryBound(to: macfont_info.self)
  let macfont = macfont_info.pointee.macfont
  var glyph_len: Int, len: Int, i: Int
  /* C declares `j` uninitialised with the rest (`ptrdiff_t glyph_len, len, i, j;`) and gives it
     its first value inside the loop below; Swift requires a variable captured by a closure to
     be initialised before the capture, so the port starts it at the record's trivial value.  */
  var j: Int = 0
  var nonbmp_len: CFIndex
  var unichars: UnsafeMutablePointer<unichar>? = nil
  var nonbmp_indices: UnsafeMutablePointer<CFIndex>? = nil
  var string: CFString?
  var used: CFIndex = 0
  var glyph_layouts: UnsafeMutablePointer<mac_glyph_layout>? = nil

  glyph_len = LGSTRING_GLYPH_LEN(lgstring)
  nonbmp_len = 0
  i = 0
  while i < glyph_len {
    let lglyph = LGSTRING_GLYPH(lgstring, i)

    if NILP(lglyph) {
      break
    }
    if LGLYPH_CHAR(lglyph) >= 0x10000 {
      nonbmp_len += 1
    }
    i += 1
  }

  len = i

  if Int(Int32.max) / 2 < len {
    memory_full_up()
  }

  return withUnsafeTemporaryAllocation(of: unichar.self,
                                       capacity: max(len + Int(nonbmp_len), 1)) { uBuf in
    unichars = uBuf.baseAddress!
    return withUnsafeTemporaryAllocation(of: CFIndex.self,
                                         capacity: Int(nonbmp_len) + 1) { nbBuf in
      nonbmp_indices = nbBuf.baseAddress!
      /* C: `for (i = j = 0; i < len; i++) …`.  */
      i = 0
      j = 0
      while i < len {
        let c = UTF32Char(LGLYPH_CHAR(LGSTRING_GLYPH(lgstring, i)))

        if macfont_store_utf32char_to_unichars(c, unichars! + i + j) > 1 {
          nonbmp_indices![j] = i + j
          j += 1
        }
        i += 1
      }
      nonbmp_indices![j] = len + j /* sentinel */

      block_input()

      string = CFStringCreateWithCharactersNoCopy(nil, unichars, len + Int(nonbmp_len),
                                                  kCFAllocatorNull)
      if string != nil {
        var dir = lgstring_direction.DIR_UNKNOWN

        if EQ(direction, QL2R()) {
          dir = lgstring_direction.DIR_L2R
        } else if EQ(direction, QR2L()) {
          dir = lgstring_direction.DIR_R2L
        }
        return withUnsafeTemporaryAllocation(of: mac_glyph_layout.self,
                                             capacity: max(glyph_len, 1)) { glBuf in
          glyph_layouts = glBuf.baseAddress!
          if macfont_info.pointee.screen_font != nil {
            used = mac_screen_font_shape(macfont_info.pointee.screen_font, string,
                                        glyph_layouts!, glyph_len, dir)
          } else {
            used = mac_font_shape(macfont, string, glyph_layouts!, glyph_len, dir)
          }

          unblock_input()

          if used == 0 {
            return Qnil()
          }

          block_input()

          i = 0
          while i < Int(used) {
            var lglyph = LGSTRING_GLYPH(lgstring, i)
            let gl = glyph_layouts! + i
            var from: Int, to: Int
            var metrics = font_metrics(lbearing: 0, rbearing: 0, width: 0, ascent: 0,
                                       descent: 0)
            var xoff: Int32, yoff: Int32, wadjust: Int32, multiplier: Int32

            if NILP(lglyph) {
              lglyph = LGLYPH_NEW()
              LGSTRING_SET_GLYPH(lgstring, i, lglyph)
            }

            from = gl.pointee.comp_range.location
            /* Convert UTF-16 index to UTF-32.  */
            j = 0
            while nonbmp_indices![j] < from {
              j += 1
            }
            from -= j
            LGLYPH_SET_FROM(lglyph, from)

            to = gl.pointee.comp_range.location + gl.pointee.comp_range.length
            /* Convert UTF-16 index to UTF-32.  */
            while nonbmp_indices![j] < to {
              j += 1
            }
            to -= j
            LGLYPH_SET_TO(lglyph, to - 1)

            /* LGLYPH_CHAR is used in `describe-char' for checking whether the composition is
               trivial.  */
            do {
              var c: UTF32Char
              let si = Int(gl.pointee.string_index)

              if unichars![si] >= 0xD800 && unichars![si] < 0xDC00 {
                c = UTF32Char(((Int(unichars![si]) - 0xD800) << 10)
                              + (Int(unichars![si + 1]) - 0xDC00) + 0x10000)
              } else {
                c = UTF32Char(unichars![si])
              }
              if macfont_get_glyph_for_character(font, c) != gl.pointee.glyph_id {
                c = 0
              }
              LGLYPH_SET_CHAR(lglyph, c)
            }

            do {
              let cc = UInt(gl.pointee.glyph_id)

              LGLYPH_SET_CODE(lglyph, cc)
            }

            _ = macfont_glyph_extents(font, gl.pointee.glyph_id, &metrics, nil, 0)
            LGLYPH_SET_WIDTH(lglyph, Int(metrics.width))
            LGLYPH_SET_LBEARING(lglyph, Int(metrics.lbearing))
            LGLYPH_SET_RBEARING(lglyph, Int(metrics.rbearing))
            LGLYPH_SET_ASCENT(lglyph, Int(metrics.ascent))
            LGLYPH_SET_DESCENT(lglyph, Int(metrics.descent))

            xoff = Int32(lround(gl.pointee.advance_delta))
            yoff = Int32(lround(-gl.pointee.baseline_delta))
            multiplier = macfont_monospace_width_multiplier(font, gl.pointee.advance)
            if multiplier != 0 {
              wadjust = font.pointee.space_width * multiplier
            } else {
              wadjust = Int32(lround(gl.pointee.advance))
            }
            if xoff != 0 || yoff != 0 || wadjust != Int32(metrics.width) {
              let vec = withUnsafeTemporaryAllocation(of: Lisp_Object.self, capacity: 3) { args in
                args[0] = make_fixnum(Int(xoff))
                args[1] = make_fixnum(Int(yoff))
                args[2] = make_fixnum(Int(wadjust))

                return Fvector(3, args.baseAddress)
              }

              LGLYPH_SET_ADJUSTMENT(lglyph, vec)
            }
            i += 1
          }

          unblock_input()

          return make_fixnum(Int(used))
        }
      }
      /* C: `unblock_input (); if (used == 0) return Qnil;` for the `string == NULL` case: the
         string is the only thing that can set `used`, so C's test is true there and the port
         returns the same `Qnil` (the branch above carries the same two statements).  */
      unblock_input()

      return Qnil()
    }
  }
}
// ==========================================================================
// Segment 1 (rc 3.184's order): `struct glyph_string` and `macfont_draw`.
// ==========================================================================

/// C: `struct glyph_slice` (src/dispextern.h 455-462) - four 16-bit bit-fields in one 8-byte
/// unit; nothing in this unit reads a member, so the port records the storage unit (P-80) and
/// adds the named accessors when a reader lands.
struct glyph_slice_unit {
  var bits: UInt64
}

/// C: `NativeRectangle` on this target is `NSRect` (src/nsterm.h; 32 bytes), so `clip[2]` is two
/// of them.
typealias NativeRectangle = NSRect

/// C: `struct glyph_string` (src/dispextern.h 1362-1507), the record `macfont_draw` reads.  The
/// owner mirror is `femacs/src/include/dispextern.rs` 1366 (behind `have_window_system`); it is
/// not layout-asserted there, so this lane measured the windowed form itself (`## Evidence`:
/// `sizeof` 272, align 8, and every offset below).  The eight-bit run at 120 holds
/// `extends_to_end_of_line_p` (bit 0), `background_filled_p` (1), `font_not_found_p` (2),
/// `stippled_p` (3), `for_overlaps` (4-6) and `padding_p` (7) - measured by dumping the byte -
/// and is stored as one `UInt8` with accessors, the shape `macfont_info`'s run uses.
struct glyph_string {
  var x: Int32
  var y: Int32
  var ybase: Int32
  var width: Int32
  var background_width: Int32
  var height: Int32
  var left_overhang: Int32
  var right_overhang: Int32
  /// C: `struct frame *f;`
  var f: UnsafeMutableRawPointer?
  /// C: `struct window *w;`
  var w: UnsafeMutableRawPointer?
  /// C: `struct glyph_row *row;`
  var row: UnsafeMutableRawPointer?
  /// C: `enum glyph_row_area area;`
  var area: Int32
  var char2b: UnsafeMutablePointer<UInt32>?
  var nchars: Int32
  /// C: `enum draw_glyphs_face hl;`
  var hl: Int32
  /// C: `struct face *face;`
  var face: UnsafeMutableRawPointer?
  var font: UnsafeMutablePointer<font>?
  /// C: `struct composition *cmp;`
  var cmp: UnsafeMutableRawPointer?
  /// C: `ptrdiff_t cmp_id;`
  var cmp_id: Int
  var cmp_from: Int32
  var cmp_to: Int32
  /// C: the eight-bit run of src/dispextern.h 1431-1461 (see the record's comment).
  var bits: UInt8
  /// C: `struct glyph *first_glyph;`
  var first_glyph: UnsafeMutableRawPointer?
  /// C: `struct image *img;`
  var img: UnsafeMutableRawPointer?
  /// C: `struct xwidget *xwidget;`
  var xwidget: UnsafeMutableRawPointer?
  var slice: glyph_slice_unit
  var clip_head: UnsafeMutablePointer<glyph_string>?
  var clip_tail: UnsafeMutablePointer<glyph_string>?
  var clip: (NativeRectangle, NativeRectangle)
  var num_clips: Int32
  var underline_position: Int32
  var underline_thickness: Int32
  var next: UnsafeMutablePointer<glyph_string>?
  var prev: UnsafeMutablePointer<glyph_string>?
}

/// C: `s->padding_p` (src/dispextern.h 1461) - bit 7 of the record's run at 120.
fileprivate func padding_p(_ s: UnsafeMutablePointer<glyph_string>) -> Bool {
  s.pointee.bits & (1 << 7) != 0
}
/// C: `s->for_overlaps` (src/dispextern.h 1456) - bits 4-6 of the same run, whose values are the
/// `OVERLAPS_*` macros (1445-1448).
fileprivate func for_overlaps(_ s: UnsafeMutablePointer<glyph_string>) -> UInt32 {
  UInt32((s.pointee.bits >> 4) & 0x7)
}

/// C: `#define CG_SET_FILL_COLOR_WITH_FACE_FOREGROUND(context, face) …` (src/macfont.m 633-638)
/// and its four siblings (639-667).  Each is a `do { … } while (0)` around `get_cgcolor`/
/// `get_cgcolor_from_nscolor` and one `CGContextSet*` call; the port spells them as five
/// fileprivate functions, and each call site in `macfont_draw` is C's own macro use
/// (`## Decisions`).
fileprivate func CG_SET_FILL_COLOR_WITH_FACE_FOREGROUND(_ context: CGContext?,
                                                        _ face: UnsafeMutableRawPointer?) {
  let refcol = get_cgcolor(NS_FACE_FOREGROUND(face))

  context!.setFillColor(refcol!)
  // C's `CGColorRelease (refcol)` is ARC's here (a `Create` result is owned in Swift).
}
fileprivate func CG_SET_FILL_COLOR_WITH_FACE_BACKGROUND(_ context: CGContext?,
                                                        _ face: UnsafeMutableRawPointer?) {
  let refcol = get_cgcolor(NS_FACE_BACKGROUND(face))

  context!.setFillColor(refcol!)
}
fileprivate func CG_SET_FILL_COLOR_WITH_FRAME_CURSOR(_ context: CGContext?,
                                                     _ frame: UnsafeMutableRawPointer?) {
  let refcol = get_cgcolor_from_nscolor(FRAME_CURSOR_COLOR(frame), frame)

  context!.setFillColor(refcol!)
}
fileprivate func CG_SET_FILL_COLOR_WITH_FRAME_BACKGROUND(_ context: CGContext?,
                                                         _ frame: UnsafeMutableRawPointer?) {
  let refcol = get_cgcolor_from_nscolor(FRAME_BACKGROUND_COLOR(frame), frame)

  context!.setFillColor(refcol!)
}
fileprivate func CG_SET_STROKE_COLOR_WITH_FACE_FOREGROUND(_ context: CGContext?,
                                                          _ face: UnsafeMutableRawPointer?) {
  let refcol = get_cgcolor(NS_FACE_FOREGROUND(face))

  context!.setStrokeColor(refcol!)
}

/// C: `macfont_draw` (src/macfont.m 2923-3089).  The `#if MAC_OS_X_VERSION_*` arms are this
/// file's own (see the ledger's table): the port takes the modern ones, which is why the
/// context is `NSGraphicsContext.currentContext.CGContext` (not the old `graphicsPort`), the
/// backing-scale factor is read unconditionally, and `CTFontDrawGlyphs` is called whenever
/// `color_bitmap_p` says so.
fileprivate func macfont_draw(_ s: UnsafeMutablePointer<glyph_string>?,
                              _ from: Int32, _ to: Int32, _ x: Int32, _ y: Int32,
                              _ with_background: Bool) -> Int32 {
  let f = s!.pointee.f
  let macfont_info =
    UnsafeMutableRawPointer(s!.pointee.font!).assumingMemoryBound(to: macfont_info.self)
  var background_rect: CGRect
  var text_position: CGPoint
  var glyphs: UnsafeMutablePointer<CGGlyph>
  var positions: UnsafeMutablePointer<CGPoint>
  let font_size = CTFontGetSize(macfont_info.pointee.macfont!)
  let no_antialias_p =
    (NILP(ns_antialias_text())
     || antialias(macfont_info) == MACFONT_ANTIALIAS_OFF
     || (antialias(macfont_info) == MACFONT_ANTIALIAS_DEFAULT
         && font_size <= macfont_antialias_threshold))
  let len = to - from
  let face = s!.pointee.face
  var context: CGContext?

  block_input()

  if with_background {
    background_rect = CGRect(x: CGFloat(x),
                             y: CGFloat(y) - CGFloat(FONT_BASE(s!.pointee.font)),
                             width: CGFloat(s!.pointee.width),
                             height: CGFloat(FONT_HEIGHT(s!.pointee.font)))
  } else {
    background_rect = CGRect.null
  }

  text_position = CGPoint(x: CGFloat(x), y: CGFloat(-y))
  glyphs = xmalloc(MemoryLayout<CGGlyph>.size * Int(len))!
    .assumingMemoryBound(to: CGGlyph.self)
  positions = xmalloc(MemoryLayout<CGPoint>.size * Int(len))!
    .assumingMemoryBound(to: CGPoint.self)
  do {
    var advance_delta: CGFloat = 0
    var total_width: CGFloat = 0
    var i: Int32 = 0

    while i < len {
      glyphs[Int(i)] = CGGlyph(truncatingIfNeeded: s!.pointee.char2b![Int(from + i)])
      let width = (padding_p(s!)
                   ? 1
                   : macfont_glyph_extents(s!.pointee.font, glyphs[Int(i)], nil,
                                           &advance_delta, no_antialias_p ? 1 : 0))

      positions[Int(i)].x = total_width + advance_delta
      positions[Int(i)].y = 0
      total_width += CGFloat(width)
      i += 1
    }
  }

  context = NSGraphicsContext.current!.cgContext
  context!.saveGState()

  if !background_rect.isNull {
    if s!.pointee.hl == DRAW_CURSOR() {
      if face != nil
          && (NS_FACE_BACKGROUND(face) == UInt(unsignedLong(FRAME_CURSOR_COLOR(f)))) {
        CG_SET_FILL_COLOR_WITH_FACE_FOREGROUND(context, face)
      } else {
        CG_SET_FILL_COLOR_WITH_FRAME_CURSOR(context, f)
      }
    } else {
      CG_SET_FILL_COLOR_WITH_FACE_BACKGROUND(context, face)
    }
    context!.fill([background_rect])
  }

  if macfont_info.pointee.cgfont != nil {
    var atfm: CGAffineTransform

    context!.scaleBy(x: 1, y: -1)
    if s!.pointee.hl == DRAW_CURSOR() {
      if face != nil
          && (NS_FACE_BACKGROUND(face) == UInt(unsignedLong(FRAME_CURSOR_COLOR(f)))) {
        CG_SET_FILL_COLOR_WITH_FACE_BACKGROUND(context, face)
      } else {
        CG_SET_FILL_COLOR_WITH_FRAME_BACKGROUND(context, f)
      }
    } else {
      CG_SET_FILL_COLOR_WITH_FACE_FOREGROUND(context, face)
    }
    if synthetic_italic_p(macfont_info) {
      atfm = synthetic_italic_atfm
    } else {
      atfm = CGAffineTransform.identity
    }
    if synthetic_bold_p(macfont_info) && !no_antialias_p {
      context!.setTextDrawingMode(.fillStroke)

      /* Stroke line width for text drawing is not correctly
         scaled on Retina display/HiDPI mode when drawn to screen
         (whereas it is correctly scaled when drawn to bitmaps),
         and synthetic bold looks thinner on such environments.
         Apple says there are no plans to address this issue
         (rdar://11644870) currently.  So we add a workaround.  */
      context!.setLineWidth(synthetic_bold_factor * font_size
                            * FRAME_NS_VIEW(f)!.window!.backingScaleFactor)
      CG_SET_STROKE_COLOR_WITH_FACE_FOREGROUND(context, face)
    }
    if no_antialias_p {
      context!.setShouldAntialias(false)
    }

    if !NILP(ns_use_thin_smoothing()) {
      context!.setShouldSmoothFonts(true)
      CGContextSetFontSmoothingStyle(context!, 16)
    }

    context!.textMatrix = atfm
    context!.textPosition = text_position

    if color_bitmap_p(macfont_info) {
      if len > 0 {
        CTFontDrawGlyphs(macfont_info.pointee.macfont!, glyphs, positions, Int(len),
                         context!)
      }
    } else {
      context!.setFont(macfont_info.pointee.cgfont!)
      context!.setFontSize(font_size)
      // The SDK's own replacement for `CGContextShowGlyphsAtPositions` takes arrays.
      context!.showGlyphs(Array(UnsafeBufferPointer(start: glyphs, count: Int(len))),
                          at: Array(UnsafeBufferPointer(start: positions, count: Int(len))))
    }
  }

  xfree(UnsafeMutableRawPointer(glyphs))
  xfree(UnsafeMutableRawPointer(positions))
  context!.restoreGState()

  unblock_input()

  return len
}

// ==========================================================================
// The three helpers C forward-declares at 49-56 and defines after this round's boundary
// (src/macfont.m 3707, 3714, 3721).  They are here because the boundary's
// `macfont_glyph_extents`/`macfont_copy_available_families_cache` call them, and C's own
// forward declaration is what makes their position free.
// ==========================================================================

/// C: `mac_font_get_advance_width_for_glyph` (src/macfont.m 3707-3712).
fileprivate func mac_font_get_advance_width_for_glyph(_ font: CTFont?, _ glyph: CGGlyph) -> Double {
  var glyph = glyph

  return CTFontGetAdvancesForGlyphs(font!, CTFontOrientation.default, &glyph, nil, 1)
}

/// C: `mac_font_get_bounding_rect_for_glyph` (src/macfont.m 3714-3719).
fileprivate func mac_font_get_bounding_rect_for_glyph(_ font: CTFont?, _ glyph: CGGlyph) -> CGRect {
  var glyph = glyph

  return CTFontGetBoundingRectsForGlyphs(font!, CTFontOrientation.default, &glyph, nil, 1)
}

/// C: `mac_font_create_available_families` (src/macfont.m 3721-3748).
fileprivate func mac_font_create_available_families() -> CFArray? {
  var families: CFMutableArray?
  let orig_families: CFArray? = CTFontManagerCopyAvailableFontFamilyNames()

  if orig_families != nil {
    let count = CFArrayGetCount(orig_families)

    families = CFArrayCreateMutable(nil, count, nil)
    if families != nil {
      var i: CFIndex = 0

      while i < count {
        let familyPtr = CFArrayGetValueAtIndex(orig_families, i)
        let family = Unmanaged<CFString>.fromOpaque(familyPtr!).takeUnretainedValue()

        if !CFStringHasPrefix(family, "." as CFString)
            && CTFontManagerCompareFontFamilyNames(
                 UnsafeRawPointer(Unmanaged.passUnretained(family).toOpaque()),
                 UnsafeRawPointer(Unmanaged.passUnretained("LastResort" as CFString).toOpaque()),
                 nil) != CFComparisonResult.compareEqualTo {
          CFArrayAppendValue(families, UnsafeRawPointer(Unmanaged.passUnretained(family).toOpaque()))
        }
        i += 1
      }
    }
  }

  return families
}


/// C: `mac_font_create_line_with_string_and_font` (src/macfont.m 3775-3836).  C's `CFRelease`s
/// of `values[1]`, `attributes`, `attr_string` and `ctline` are ARC's here; `values[1]` keeps
/// C's own role (the `CFNumberCreate` result, whose NULL is the test C makes).  The
/// `if (attributes == NULL) break;` inside the runs loop is the `CTRunGetAttributes`
/// deviation `mac_font_create_preferred_family_for_attributes` records (the SDK imports that
/// copy as non-optional), so only the `font_in_run == NULL` guard is written.
fileprivate func mac_font_create_line_with_string_and_font(_ string: CFString?,
                                                           _ macfont: CTFont?) -> CTLine? {
  var keys: [UnsafeRawPointer?] = [
    UnsafeRawPointer(Unmanaged.passUnretained(kCTFontAttributeName).toOpaque()),
    UnsafeRawPointer(Unmanaged.passUnretained(kCTKernAttributeName).toOpaque())
  ]
  var values: [UnsafeRawPointer?] = [
    UnsafeRawPointer(Unmanaged.passUnretained(macfont!).toOpaque()), nil
  ]
  var attributes: CFDictionary? = nil
  var attr_string: CFAttributedString? = nil
  var ctline: CTLine? = nil
  var float_zero: Float = 0.0
  let kern = CFNumberCreate(nil, CFNumberType.floatType, &float_zero)

  values[1] = kern == nil
    ? nil
    : UnsafeRawPointer(Unmanaged.passUnretained(kern!).toOpaque())
  if values[1] != nil {
    attributes = keys.withUnsafeMutableBufferPointer { kb in
      values.withUnsafeMutableBufferPointer { vb in
        withUnsafePointer(to: kCFTypeDictionaryKeyCallBacks) { keyCallbacks in
          withUnsafePointer(to: kCFTypeDictionaryValueCallBacks) { valueCallbacks in
            CFDictionaryCreate(nil, kb.baseAddress, vb.baseAddress, 2,
                               keyCallbacks, valueCallbacks)
          }
        }
      }
    }
  }
  if attributes != nil {
    attr_string = CFAttributedStringCreate(nil, string, attributes)
  }
  if attr_string != nil {
    ctline = CTLineCreateWithAttributedString(attr_string!)
  }
  if ctline != nil {
    /* Abandon if ctline contains some fonts other than the specified one.  */
    let runs = CTLineGetGlyphRuns(ctline!)
    let nruns = CFArrayGetCount(runs)
    var i: CFIndex = 0

    while i < nruns {
      let run = Unmanaged<CTRun>.fromOpaque(CFArrayGetValueAtIndex(runs, i)!)
        .takeUnretainedValue()
      /* C's `CFDictionaryRef attributes = CTRunGetAttributes (run);` shadows the parameter.  */
      let attributes = CTRunGetAttributes(run)
      let font_in_run = CFDictionaryGetValue(attributes,
                                             UnsafeRawPointer(Unmanaged.passUnretained(
                                               kCTFontAttributeName).toOpaque()))

      if font_in_run == nil {
        break
      }
      if !mac_font_equal_in_postscript_name(macfont,
                                            Unmanaged<CTFont>.fromOpaque(font_in_run!)
                                              .takeUnretainedValue()) {
        break
      }
      i += 1
    }
    if i < nruns {
      ctline = nil
    }
  }

  return ctline
}

/// C: `mac_font_shape` (src/macfont.m 3839-3988).  `RIGHT_TO_LEFT_P` is C's
/// `#define RIGHT_TO_LEFT_P permutation` (3870), and **here it is live text** - `permutation`
/// is `xmalloc`'d for a right-to-left run and freed with `xfree` - so the port keeps C's
/// `permutation != nil` expressions (the shape `mac_font_shape_1` already uses); C's
/// `CFRelease (ctline)` is ARC's.  C's `dir` parameter is unused in this function and is kept
/// as C declares it (the caller's `DIR_UNKNOWN`/`DIR_L2R`/`DIR_R2L` choice is only read by the
/// `mac_screen_font_shape` arm).
fileprivate func mac_font_shape(_ font: CTFont?, _ string: CFString?,
                                _ glyph_layouts: UnsafeMutablePointer<mac_glyph_layout>,
                                _ glyph_len: CFIndex,
                                _ dir: lgstring_direction) -> CFIndex {
  var used: CFIndex, result: CFIndex = 0
  let ctline = mac_font_create_line_with_string_and_font(string, font)

  if ctline == nil {
    return 0
  }

  used = CTLineGetGlyphCount(ctline!)
  if used <= glyph_len {
    let ctruns = CTLineGetGlyphRuns(ctline!)
    let ctrun_count = CFArrayGetCount(ctruns)
    var total_advance: CGFloat = 0
    var total_glyph_count: CFIndex = 0
    var k: CFIndex = 0

    while k < ctrun_count {
      let ctrun = Unmanaged<CTRun>.fromOpaque(CFArrayGetValueAtIndex(ctruns, k)!)
        .takeUnretainedValue()
      let glyph_count = CTRunGetGlyphCount(ctrun)
      let glbuf = glyph_layouts + total_glyph_count
      var string_range: CFRange, comp_range: CFRange, range: CFRange
      var permutation: UnsafeMutablePointer<CFIndex>?
      var i: CFIndex, min_location: CFIndex

      if CTRunGetStatus(ctrun).contains(CTRunStatus.rightToLeft) {
        permutation = xmalloc(MemoryLayout<CFIndex>.size * Int(glyph_count))!
          .assumingMemoryBound(to: CFIndex.self)
      } else {
        permutation = nil
      }

      /* Now the `comp_range' member of struct mac_glyph_layout is temporarily used as a work
         area such that:
         glbuf[i].comp_range.location =
         min {compRange[i + 1].location, ..., compRange[glyph_count - 1].location,
              maxRange (stringRangeForCTRun)}
         glbuf[i].comp_range.length = maxRange (compRange[i])
         where compRange[i] is the range of composed characters containing i-th glyph.  */
      string_range = CTRunGetStringRange(ctrun)
      min_location = string_range.location + string_range.length
      i = 0
      while i < glyph_count {
        let gl = glbuf + glyph_count - i - 1
        var glyph_index: CFIndex
        var rng: CFRange

        if permutation == nil {
          glyph_index = glyph_count - i - 1
        } else {
          glyph_index = i
        }
        CTRunGetStringIndices(ctrun, CFRangeMake(glyph_index, 1), &gl.pointee.string_index)
        rng = CFStringGetRangeOfComposedCharactersAtIndex(string!, gl.pointee.string_index)
        gl.pointee.comp_range.location = min_location
        gl.pointee.comp_range.length = rng.location + rng.length
        if rng.location < min_location {
          min_location = rng.location
        }
        i += 1
      }

      /* Fill the `comp_range' member of struct mac_glyph_layout, and setup a permutation for
         right-to-left text.  */
      comp_range = CFRangeMake(string_range.location, 0)
      range = CFRangeMake(0, 0)
      while true {
        let gl = glbuf + range.location + range.length

        if gl.pointee.comp_range.length > comp_range.location + comp_range.length {
          comp_range.length = gl.pointee.comp_range.length - comp_range.location
        }
        min_location = gl.pointee.comp_range.location
